def koopa_pack(raw_bytes):
    return base64.b64encode(zlib.compress(raw_bytes, 9)).decode('ascii')

def koopa_unpack(b64):
    data = b64 if isinstance(b64, str) else ''.join(b64)
    return zlib.decompress(base64.b64decode(data))

def koopa_unpack_json(b64):
    return json.loads(koopa_unpack(b64))

KOOPA_MUSIC_RATE = 11025          # embedded PCM / WAV sample rate (SMBX 1.3)
KOOPA_MUSIC_MIXER = (11025, -16, 1, 512)  # match PCM — 16-bit mono for pygame


def koopa_music_pcm_to_wav(pcm, rate=None):
    """8-bit mono PCM -> 16-bit mono WAV at KOOPA_MUSIC_RATE (pygame-safe)."""
    rate = rate or KOOPA_MUSIC_RATE
    pcm16 = struct.pack('<' + 'h' * len(pcm), *[(b - 128) * 256 for b in pcm])
    n = len(pcm16)
    return struct.pack(
        '<4sI4s4sIHHIIHH4sI',
        b'RIFF', 36 + n, b'WAVE', b'fmt ', 16, 1, 1,
        rate, rate, 2, 16, b'data', n,
    ) + pcm16


def koopa_pack_music_megapack(pcm_by_id):
    items = sorted((int(k), v) for k, v in pcm_by_id.items())
    blob = struct.pack('<I', len(items))
    concat = bytearray()
    for mid, pcm in items:
        off = len(concat)
        blob += struct.pack('<HII', mid, off, len(pcm))
        concat.extend(pcm)
    blob += bytes(concat)
    return base64.b64encode(zlib.compress(bytes(blob), 9)).decode('ascii')


def koopa_unpack_music_megapack(b64):
    raw = zlib.decompress(base64.b64decode(b64 if isinstance(b64, str) else ''.join(b64)))
    count = struct.unpack_from('<I', raw, 0)[0]
    pos = 4
    index = []
    for _ in range(count):
        mid, off, ln = struct.unpack_from('<HII', raw, pos)
        index.append((mid, off, ln))
        pos += 10
    pcm_blob = raw[pos:]
    return {mid: pcm_blob[off:off + ln] for mid, off, ln in index}

