SMBX_MUSIC_ID_GHOST_HOUSE = SMBX_MUSIC_DECOMP_BY_FILE["smw-ghosthouse.mp3"]


def smbx_music_decomp_id(filename):
    """Resolve SMBX bgMusic slot from modSound.bas mp3 filename."""
    fn = str(filename or "").strip().lower()
    if not fn:
        return None
    if fn in SMBX_MUSIC_DECOMP_BY_FILE:
        return SMBX_MUSIC_DECOMP_BY_FILE[fn]
    if not fn.endswith(".mp3"):
        return SMBX_MUSIC_DECOMP_BY_FILE.get(fn + ".mp3")
    return None


