SMBX_BG_ID_GHOST_HOUSE = SMBX_BACKGROUND_DECOMP_BY_CAPTION["Ghost House"]
SMBX_GHOST_HOUSE_BG_COLOR = (0, 0, 0)  # SMBX ghost-house sections use black backdrop


def smbx_background_decomp_id(caption):
    return SMBX_BACKGROUND_DECOMP_BY_CAPTION.get(str(caption or "").strip())


def apply_smbx_ghost_house_section(section):
    """Apply SMBX 1.3 decomp ghost-house defaults (bg #18, music #17, black)."""
    section.bg_type = SMBX_BG_ID_GHOST_HOUSE
    section.bg_color = SMBX_GHOST_HOUSE_BG_COLOR
    section.music = SMBX_MUSIC_ID_GHOST_HOUSE
    section.music_file = SMBX_MUSIC_DECOMP.get(SMBX_MUSIC_ID_GHOST_HOUSE, "")

SMBX_MUSIC_IDS = tuple(SMBX_MUSIC_LABELS.keys())
KOOPA_MUSIC_IDS = {i: i for i in SMBX_MUSIC_IDS}
KOOPA_MUSIC_LABELS = SMBX_MUSIC_LABELS

def smbx_music_label(music_id):
    try:
        mid = int(music_id)
    except (TypeError, ValueError):
        return "ID ?"
    return SMBX_MUSIC_LABELS.get(mid, f"ID {mid}")


def smbx_music_step(music_id, delta=1):
    ids = SMBX_MUSIC_IDS
    if not ids:
        return 1
    try:
        idx = ids.index(int(music_id))
    except ValueError:
        return ids[0]
    return ids[(idx + delta) % len(ids)]



