SMBX_NPC_BY_ID = {int(k): dict(v) for k, v in SMBX_NPC_BY_ID_RAW.items()}

def smbx_npc_id_from_decomp(name):
    """Resolve SMBX NPC slot from SMBX_NPC_BY_ID decomp name."""
    for nid, meta in SMBX_NPC_BY_ID.items():
        if meta.get("name") == name:
            return nid
    return None

for _m in SMBX_NPC_BY_ID.values():
    _m.pop('walk_ai', None)
del SMBX_NPC_BY_ID_RAW


# modNPC.bas ghost house NPCs — sheet is 4 frames tall (128px / gfx_h 32)
for _gid, _algo, _spd in ((42, "rush", 2.0), (43, "boo", 1.0)):
    _gm = SMBX_NPC_BY_ID.get(_gid)
    if _gm:
        _gm.update(algorithm=_algo, speed=_spd, frames=4, gfx_h=32, hurts_stomp=1)

for _ghost_name in ("ghost_1", "ghost_2"):
    _gid = smbx_npc_id_from_decomp(_ghost_name)
    if _gid is not None:
        SMBX_NPC_IDS[_ghost_name] = _gid


