class MusicAddon:
    """Koopa worker community edition music addon — SMBX 1.3 WAV OST (FILES=OFF zlib+b64)."""
    _inst = None

    def __init__(self):
        self._sounds = {}
        self._volume = 0.65
        self._current_key = None
        self._ensure_mixer()

    @classmethod
    def get(cls):
        if cls._inst is None:
            cls._inst = MusicAddon()
        return cls._inst

    def _ensure_mixer(self):
        want = KOOPA_MUSIC_MIXER
        cur = pygame.mixer.get_init()
        if cur == want:
            return
        if cur:
            pygame.mixer.quit()
            self._sounds.clear()
        for freq, size, ch, buf in (want, (22050, -16, 1, 512), (44100, -16, 2, 1024)):
            try:
                pygame.mixer.init(frequency=freq, size=size, channels=ch, buffer=buf)
                if pygame.mixer.get_init():
                    return
            except pygame.error:
                continue

    def _load_sound(self, mid):
        try:
            mid = int(mid)
        except (TypeError, ValueError):
            return None
        if mid in self._sounds:
            return self._sounds[mid]
        pcm = SMBX_MUSIC_PCM.get(mid)
        if not pcm:
            return None
        try:
            wav = koopa_music_pcm_to_wav(pcm, rate=KOOPA_MUSIC_RATE)
            snd = pygame.mixer.Sound(io.BytesIO(wav))
            self._sounds[mid] = snd
            return snd
        except (pygame.error, ValueError, zlib.error, struct.error):
            return None

    def play_id(self, music_id):
        try:
            mid = int(music_id)
        except (TypeError, ValueError):
            mid = 1
        if mid <= 0:
            self.stop()
            return
        if mid not in SMBX_MUSIC_PCM or mid not in SMBX_MUSIC_LABELS:
            mid = 1
        self.play_key(mid)

    def play_key(self, key):
        snd = self._load_sound(key)
        if not snd:
            return
        key = int(key)
        if self._current_key == key and pygame.mixer.get_busy():
            return
        self.stop()
        snd.set_volume(self._volume)
        snd.play(-1)
        self._current_key = key

    def stop(self):
        self._current_key = None
        if pygame.mixer.get_init():
            pygame.mixer.stop()

    def set_volume(self, vol):
        self._volume = max(0.0, min(1.0, vol))


pygame.mixer.pre_init(frequency=KOOPA_MUSIC_MIXER[0], size=KOOPA_MUSIC_MIXER[1], channels=KOOPA_MUSIC_MIXER[2], buffer=KOOPA_MUSIC_MIXER[3])
