def draw_mw_sky(surf, rect):
    """Mario Worker / Mario Forever blue-sky gradient."""
    if rect.height <= 0:
        return
    for row in range(rect.height):
        t = row / max(rect.height - 1, 1)
        col = tuple(int(MW_SKY_TOP[i] * (1 - t) + MW_SKY_BOT[i] * t) for i in range(3))
        y = rect.y + row
        pygame.draw.line(surf, col, (rect.x, y), (rect.right - 1, y))




def draw_smbx_ghost_house_bg(surf, rect):
    """Procedural SMW ghost-house backdrop (background-18.gif, files=off)."""
    surf.fill((0, 0, 0), rect)
    t = pygame.time.get_ticks() // 48
    pillar = (48, 32, 64)
    edge = (24, 16, 40)
    for x in range(rect.x - (t % 64), rect.right + 64, 64):
        pr = pygame.Rect(x, rect.y, 32, rect.height)
        if pr.colliderect(rect):
            pygame.draw.rect(surf, pillar, pr)
            pygame.draw.line(surf, edge, (pr.x, pr.top), (pr.x, pr.bottom))
            pygame.draw.line(surf, edge, (pr.right - 1, pr.top), (pr.right - 1, pr.bottom))
    band = rect.y + ((t // 2) % 32)
    for y in range(band, rect.bottom, 32):
        pygame.draw.line(surf, (12, 8, 20), (rect.x, y), (rect.right, y), 1)


def draw_smbx_section_bg(surf, rect, section):
    """Section sky/backdrop — SMBX decomp background id when set."""
    bg_type = int(getattr(section, "bg_type", 0) or 0)
    sec_bg = getattr(section, "bg_color", (92, 148, 252))
    if bg_type == SMBX_BG_ID_GHOST_HOUSE:
        draw_smbx_ghost_house_bg(surf, rect)
        return
    if sec_bg[:3] == MW_SKY_TOP:
        draw_mw_sky(surf, rect)
    else:
        surf.fill(sec_bg, rect)

def draw_mw_scenery(surf):
    """Hills + clouds like Mario Worker v1.0 main screen."""
    pygame.draw.ellipse(surf, MW_HILL2, (-40, WINDOW_HEIGHT - 70, 220, 90))
    pygame.draw.ellipse(surf, MW_HILL, (120, WINDOW_HEIGHT - 58, 260, 80))
    pygame.draw.ellipse(surf, MW_HILL, (360, WINDOW_HEIGHT - 64, 300, 86))
    for cx, cy, w, h in ((90, 90, 72, 28), (420, 70, 88, 32), (280, 120, 64, 24)):
        pygame.draw.ellipse(surf, WHITE, (cx, cy, w, h))
        pygame.draw.ellipse(surf, WHITE, (cx + w // 3, cy - h // 3, w // 2, h // 2))


def draw_edge(surf, rect, raised=True):
    r = pygame.Rect(rect)
    tl  = SYS_BTN_LIGHT  if raised else SYS_BTN_DK_SHD
    br  = SYS_BTN_DK_SHD if raised else SYS_BTN_LIGHT
    tli = SYS_BTN_FACE    if raised else SYS_BTN_DARK
    bri = SYS_BTN_DARK    if raised else SYS_BTN_FACE
    pygame.draw.line(surf, tl,  r.topleft,    r.topright)
    pygame.draw.line(surf, tl,  r.topleft,    r.bottomleft)
    pygame.draw.line(surf, br,  r.bottomleft, r.bottomright)
    pygame.draw.line(surf, br,  r.topright,   r.bottomright)
    pygame.draw.line(surf, tli, (r.left+1,r.top+1),    (r.right-1,r.top+1))
    pygame.draw.line(surf, tli, (r.left+1,r.top+1),    (r.left+1,r.bottom-1))
    pygame.draw.line(surf, bri, (r.left+1,r.bottom-1), (r.right-1,r.bottom-1))
    pygame.draw.line(surf, bri, (r.right-1,r.top+1),   (r.right-1,r.bottom-1))


def draw_text(surf, text, pos, color=SYS_TEXT, font=FONT, center=False):
    t = font.render(str(text), True, color)
    r = t.get_rect(center=pos) if center else t.get_rect(topleft=pos)
    surf.blit(t, r)


