def _flip_h(grid):
    return [row[::-1] for row in grid]

def px_surf(grid, palette, hd=None):
    hd = hd or SPRITE_HD
    h = len(grid)
    w = max((len(r) for r in grid), default=16)
    surf = pygame.Surface((w * hd, h * hd), pygame.SRCALPHA)
    for y, row in enumerate(grid):
        row = row.ljust(w)[:w]
        for x, ch in enumerate(row):
            if ch in ('.', ' '):
                continue
            c = palette.get(ch)
            if c:
                pygame.draw.rect(surf, c, (x * hd, y * hd, hd, hd))
    return surf

NES_TALL_ROWS = 24          # SMB1 Koopa / Paratroopa OAM slot height
SMBX_KOOPA_TYPES = frozenset({
    'koopa_green', 'koopa_red', 'koopa_shell_green', 'koopa_shell_red',
    'paratroopa_green', 'paratroopa_red',
})

TALL_NPC_TYPES = frozenset({
    'koopa_green', 'koopa_red', 'paratroopa_green', 'paratroopa_red',
})

def _pad_grid_bottom(grid, rows=NES_TALL_ROWS, cols=16):
    """Pad CHR grid to fixed NES canvas — feet on bottom row (stops walk-frame pop)."""
    w = max(max(len(r) for r in grid), cols)
    chunk = [list(r.ljust(w)[:w]) for r in grid]
    used = [i for i, row in enumerate(chunk) if any(c not in '. ' for c in row)]
    if not used:
        return ['.' * cols for _ in range(rows)]
    content = chunk[used[0]:used[-1] + 1]
    out = [['.'] * cols for _ in range(rows)]
    start = rows - len(content)
    for i, row in enumerate(content):
        out[start + i] = row[:cols]
    return [''.join(r) for r in out]

def nes_sprite(grid, palette, *, tall=False):
    """Famicom CHR grid → 2× nearest-neighbor."""
    if tall:
        grid = _pad_grid_bottom(grid)
    return px_surf(grid, palette, hd=NES_HD)

def _npc_meta(npc_type):
    meta = SMBX_NPC_META.get(npc_type)
    if meta:
        return meta
    tid = NPC_SMBX_IDS.get(npc_type)
    if tid and tid in SMBX_NPC_BY_ID:
        m = dict(SMBX_NPC_BY_ID[tid])
        m.pop('name', None)
        return m
    return None


def _npc_meta_by_id(npc_id):
    m = SMBX_NPC_BY_ID.get(int(npc_id))
    if not m:
        return None
    out = dict(m)
    out.pop('name', None)
    return out

def _npc_horiz_speed(npc):
    """SMBX modNPC.bas: SpeedX = NPCWalkingSpeed * NPCSpeedvar * Direction."""
    meta = _npc_meta(npc.npc_type)
    if not meta or npc.is_not_moving:
        return 0.0
    if _npc_algorithm(npc) == 'shell' or npc.state == 'shell':
        if not npc.shell_moving:
            return 0.0
        return _smbx_tick(SMBX_PHYSICS['npc_shell_speed']) * npc.direction
    return _smbx_tick(SMBX_PHYSICS['npc_walking_speed'] * meta.get('speed', 1.0)) * npc.direction

def _npc_cliff_ahead(npc, solid_tiles):
    """SMBX cliffturn=1 — turn at ledges (red koopa)."""
    meta = _npc_meta(npc.npc_type)
    if not meta or not meta.get('cliffturn'):
        return False
    ahead = npc.rect.right + 4 if npc.direction > 0 else npc.rect.left - 12
    probe = pygame.Rect(ahead, npc.rect.bottom, 8, 8)
    for t in solid_tiles:
        if t.tile_type in ('water', 'lava', 'coin'):
            continue
        if t.rect.colliderect(probe):
            return False
    return True

def _tile_blocks_upward(tile):
    """Semisolid (id 190) — pass through from below."""
    return tile.tile_type != 'semisolid'

def _npc_algorithm(npc):
    meta = _npc_meta(npc.npc_type)
    return meta.get('algorithm', 'walk') if meta else 'walk'

def _npc_on_ground(npc, solid_tiles):
    probe = pygame.Rect(npc.rect.x + 2, npc.rect.bottom, max(4, npc.rect.width - 4), 4)
    for t in solid_tiles:
        if t.tile_type in ('water', 'lava', 'coin'):
            continue
        if not _tile_blocks_upward(t):
            continue
        if probe.colliderect(t.rect):
            return True
    return False

def _npc_apply_meta_size(npc):
    meta = _npc_meta(npc.npc_type)
    if meta:
        npc.rect.width = meta.get('phys_w', GRID_SIZE)
        npc.rect.height = meta.get('phys_h', GRID_SIZE)

def _npc_turn(npc):
    npc.direction *= -1
    meta = _npc_meta(npc.npc_type)
    if meta and meta.get('frame_style') == 1:
        npc.anim_frame = _editor_npc_frame(npc.npc_type, npc.direction)
    else:
        _clamp_smbx_frame(npc)

def _npc_walk_motion(npc, solid_tiles):
    if _npc_cliff_ahead(npc, solid_tiles):
        _npc_turn(npc)
    npc.velocity.x = _npc_horiz_speed(npc)

def _ai_paratroopa(npc, solid_tiles, player):
    """SMBX para-koopa.lua — special_data selects AI mode (default 1)."""
    mode = int(npc.special_data) if npc.special_data else 1
    span = GRID_SIZE * 4
    if mode == 0 and player is not None:
        dx = player.rect.centerx - npc.rect.centerx
        dy = player.rect.centery - npc.rect.centery
        npc.direction = 1 if dx >= 0 else -1
        npc.velocity.x = _smbx_tick(SMBX_PHYSICS['npc_walking_speed']) * npc.direction
        if dy < -16:
            npc.velocity.y = -_smbx_tick(2.0)
        elif dy > 32:
            npc.velocity.y = _smbx_tick(1.5)
        else:
            npc.velocity.y *= 0.9
    elif mode == 1:
        npc.velocity.x = _npc_horiz_speed(npc)
        if _npc_on_ground(npc, solid_tiles):
            npc.velocity.y = -_smbx_tick(18.75 * 0.55)
    elif mode == 2:
        base_x = npc.spawn_x
        if npc.rect.centerx > base_x + span:
            npc.direction = -1
        elif npc.rect.centerx < base_x - span:
            npc.direction = 1
        npc.velocity.x = _npc_horiz_speed(npc)
        npc.velocity.y = math.sin(npc.frame * 0.08) * _smbx_tick(0.5)
    else:
        base_y = npc.spawn_y
        if npc.rect.centery > base_y + span:
            npc.velocity.y = -_smbx_tick(1.2)
        elif npc.rect.centery < base_y - span:
            npc.velocity.y = _smbx_tick(1.2)
        else:
            npc.velocity.y = _smbx_tick(0.6) if npc.velocity.y >= 0 else -_smbx_tick(0.6)
        npc.velocity.x = 0

def _ai_piranha(npc, player):
    """SMBX piranha_plant.lua — rise/fall; hide when player is beside pipe."""
    if player and abs(player.rect.centerx - npc.rect.centerx) < GRID_SIZE * 1.5:
        npc.velocity.y = _smbx_tick(1.5)
        return
    if not hasattr(npc, '_piranha_up'):
        npc._piranha_up = True
    limit = GRID_SIZE * 2
    base = npc.spawn_y
    if npc._piranha_up:
        npc.velocity.y = -_smbx_tick(0.8)
        if npc.rect.top <= base - limit:
            npc._piranha_up = False
    else:
        npc.velocity.y = _smbx_tick(0.8)
        if npc.rect.top >= base:
            npc._piranha_up = True
    npc.velocity.x = 0

def _ai_powerup(npc, solid_tiles):
    spd = SMBX_PHYSICS.get('npc_mushroom_speed', SMBX_PHYSICS['npc_walking_speed'])
    npc.velocity.x = _smbx_tick(spd) * npc.direction
    if _npc_on_ground(npc, solid_tiles) and npc.velocity.y > 0:
        npc.velocity.y = -_smbx_tick(6.0)

def _ai_star(npc, solid_tiles):
    if not npc.velocity.x:
        npc.velocity.x = _npc_horiz_speed(npc) or _smbx_tick(2.0) * npc.direction
    if _npc_on_ground(npc, solid_tiles) and npc.velocity.y > 0:
        npc.velocity.y = -_smbx_tick(8.0)

def _ai_rush(npc):
    npc.velocity.x = _smbx_tick(SMBX_PHYSICS['npc_walking_speed'] * _npc_meta(npc.npc_type).get('speed', 4.0))
    npc.velocity.x *= npc.direction

def _ai_fly_h(npc, solid_tiles):
    _npc_walk_motion(npc, solid_tiles)
    npc.velocity.y = math.sin(npc.frame * 0.06) * _smbx_tick(0.4)

def _ai_podoboo(npc):
    base = npc.spawn_y
    npc.velocity.x = 0
    npc.velocity.y = math.sin(npc.frame * 0.12) * _smbx_tick(2.5)
    npc.rect.centery = int(base + math.sin(npc.frame * 0.12) * GRID_SIZE)

def _ai_thwomp(npc, player, solid_tiles):
    if not hasattr(npc, '_thwomp_state'):
        npc._thwomp_state = 'wait'
        npc._thwomp_y = npc.rect.y
    if npc._thwomp_state == 'wait' and player and player.rect.centerx > npc.rect.left - 64:
        if player.rect.centerx < npc.rect.right + 64 and player.rect.bottom > npc.rect.top:
            npc._thwomp_state = 'fall'
    if npc._thwomp_state == 'fall':
        npc.velocity.y = _smbx_tick(12.0)
        if _npc_on_ground(npc, solid_tiles):
            npc._thwomp_state = 'rise'
    elif npc._thwomp_state == 'rise':
        npc.velocity.y = -_smbx_tick(1.0)
        if npc.rect.y <= npc._thwomp_y:
            npc.rect.y = npc._thwomp_y
            npc.velocity.y = 0
            npc._thwomp_state = 'wait'
    else:
        npc.velocity.y = 0

def _ai_boo(npc, player):
    if player is None:
        npc.velocity.x = npc.velocity.y = 0
        return
    facing = (player.direction > 0 and player.rect.centerx < npc.rect.centerx) or (
        player.direction < 0 and player.rect.centerx > npc.rect.centerx)
    if facing:
        dx = 1 if player.rect.centerx > npc.rect.centerx else -1
        dy = 1 if player.rect.centery > npc.rect.centery else -1
        npc.velocity.x = _smbx_tick(1.2) * dx
        npc.velocity.y = _smbx_tick(0.8) * dy
    else:
        npc.velocity.x *= 0.5
        npc.velocity.y *= 0.5

def _ai_orbit(npc):
    ang = npc.frame * 0.05 + (npc.special_data or 0) * 0.3
    r = GRID_SIZE * 3
    npc.rect.centerx = int(npc.spawn_x + math.cos(ang) * r)
    npc.rect.centery = int(npc.spawn_y + math.sin(ang) * r)
    npc.velocity.x = npc.velocity.y = 0

def _ai_cheep(npc):
    npc.velocity.x = _npc_horiz_speed(npc)
    npc.velocity.y = math.sin(npc.frame * 0.1) * _smbx_tick(0.6)

def _ai_blooper(npc, player):
    npc.velocity.x = 0
    if player and npc.frame % 90 < 45:
        npc.velocity.y = _smbx_tick(1.5) if player.rect.centery > npc.rect.centery else -_smbx_tick(1.5)
    else:
        npc.velocity.y = -_smbx_tick(1.0)

def _smbx_npc_ai(npc, solid_tiles, player):
    """SMBX 1.3 algorithm dispatch (modNPC.bas + lua scripts)."""
    algo = _npc_algorithm(npc)
    if algo == 'shell':
        if not npc.shell_moving:
            npc.velocity.x = 0
        else:
            if _npc_cliff_ahead(npc, solid_tiles):
                _npc_turn(npc)
            npc.velocity.x = _npc_horiz_speed(npc)
        return
    if algo == 'static':
        npc.velocity.x = 0
        npc.velocity.y = 0
        return
    if algo == 'walk':
        if not npc.is_not_moving:
            _npc_walk_motion(npc, solid_tiles)
        return
    if algo == 'para':
        _ai_paratroopa(npc, solid_tiles, player)
        return
    if algo == 'piranha':
        _ai_piranha(npc, player)
        return
    if algo == 'powerup':
        _ai_powerup(npc, solid_tiles)
        return
    if algo == 'star':
        _ai_star(npc, solid_tiles)
        return
    if algo == 'rush':
        _ai_rush(npc)
        return
    if algo == 'fly_h':
        _ai_fly_h(npc, solid_tiles)
        return
    if algo == 'podoboo':
        _ai_podoboo(npc)
        return
    if algo == 'thwomp':
        _ai_thwomp(npc, player, solid_tiles)
        return
    if algo == 'boo':
        _ai_boo(npc, player)
        return
    if algo == 'orbit':
        _ai_orbit(npc)
        return
    if algo == 'cheep':
        _ai_cheep(npc)
        return
    if algo == 'blooper':
        _ai_blooper(npc, player)
        return

def _npc_shell_kick(npc, by_player):
    npc.shell_moving = True
    npc.direction = 1 if by_player.rect.centerx < npc.rect.centerx else -1
    npc.velocity.x = _npc_horiz_speed(npc)

def _npc_stomp_resolve(npc):
    """SMBX stomp chain: para → koopa → shell → (moving shell)."""
    meta = _npc_meta(npc.npc_type) or {}
    if meta.get('hurts_stomp'):
        return False
    if meta.get('koopa_type'):
        npc.npc_type = meta['koopa_type']
        npc.state = 'normal'
        _npc_apply_meta_size(npc)
        npc.anim_frame = _editor_npc_frame(npc.npc_type, npc.direction)
        npc.update_image()
        return True
    shell_type = meta.get('shell_type')
    if shell_type and npc.state != 'shell':
        npc.npc_type = shell_type
        npc.state = 'shell'
        npc.shell_moving = False
        npc.velocity.x = 0
        _npc_apply_meta_size(npc)
        npc.anim_frame = 0
        npc.update_image()
        return True
    if _npc_algorithm(npc) == 'shell' or npc.state == 'shell':
        if npc.shell_moving:
            npc.shell_moving = False
            npc.velocity.x = 0
        return True
    if meta.get('kill_onjump', 0):
        npc.kill()
        return True
    return False

def _npc_vs_npcs(npc, others):
    if not npc.shell_moving:
        return
    for other in others:
        if other is npc or not other.is_tangible:
            continue
        if not npc.rect.colliderect(other.rect):
            continue
        ometa = _npc_meta(other.npc_type) or {}
        if ometa.get('algorithm') == 'shell' and other.shell_moving:
            continue
        if ometa.get('kill_onjump', 0) or ometa.get('shell_type') or ometa.get('koopa_type'):
            other.kill()

def _smbx_anim_tick(meta, frame):
    """Map game frame to SMBX frame-delay cycles (legacy tick rate)."""
    delay = max(meta.get('frame_delay', 128), 1)
    return (frame * SMBX_TICK_HZ // FPS) // max(delay // 8, 1)

def _smbx_anim_index(meta, frame, direction):
    tick = _smbx_anim_tick(meta, frame)
    frames = max(meta.get('frames', 1), 1)
    style = meta.get('frame_style', 0)
    if style == 1 and frames >= 2:
        half = max(frames // 2, 1)
        walk = tick % half
        return walk if direction >= 0 else min(walk + half, frames - 1)
    return tick % frames

def _smbx_type_id(npc_type):
    return NPC_SMBX_IDS.get(npc_type, 1)

def _editor_npc_frame(npc_type, direction):
    """SMBX modEditor.bas EditorNPCFrame — initial sheet row per direction."""
    meta = _npc_meta(npc_type)
    if not meta:
        return 0
    frames = max(meta.get('frames', 1), 1)
    d = -1 if direction < 0 else 1
    if meta.get('frame_style', 0) == 1:
        if npc_type in ('hammer_bro', 'sledge_bro'):
            return 0 if d < 0 else 3
        if npc_type in ('bullet_bill', 'bomber_bill', 'bowser_statue'):
            return 0 if d < 0 else 1
        return 0 if d < 0 else frames
    return 0

def _clamp_smbx_frame(npc):
    """SMBX modNPC.bas NPCFrames clamp/wrap."""
    meta = _npc_meta(npc.npc_type)
    if not meta:
        return
    frames = max(meta.get('frames', 1), 1)
    style = meta.get('frame_style', 0)
    f = npc.anim_frame
    d = -1 if npc.direction < 0 else 1
    if style == 0:
        if f >= frames:
            npc.anim_frame = 0
        if f < 0:
            npc.anim_frame = frames - 1
    elif style == 1:
        if d < 0:
            if f >= frames:
                npc.anim_frame = 0
            if f < 0:
                npc.anim_frame = frames - 1
        else:
            if f >= frames * 2:
                npc.anim_frame = frames
            if f < frames:
                npc.anim_frame = frames
    elif style == 2:
        if d < 0:
            if f >= frames:
                npc.anim_frame = 0
            if f < 0:
                npc.anim_frame = frames - 1
        else:
            if f >= frames * 2:
                npc.anim_frame = frames
            if f < frames:
                npc.anim_frame = frames * 2 - 1

def _tick_smbx_frames(npc):
    """SMBX modNPC.bas NPCFrames — 65 Hz frame-delay ticks."""
    meta = _npc_meta(npc.npc_type)
    if not meta or meta.get('frames', 0) <= 0:
        return False
    frames = meta['frames']
    style = meta.get('frame_style', 0)
    speed = max(round(meta.get('frame_delay', 128) * FPS / SMBX_TICK_HZ), 1)
    npc.anim_count += 1
    if npc.anim_count < speed:
        return False
    npc.anim_count = 0
    if style == 0:
        npc.anim_frame += npc.direction
    else:
        npc.anim_frame += 1
    _clamp_smbx_frame(npc)
    return True

def _npc_blit_pos(npc, cam_x, cam_y):
    """SMBX gfx anchor — center wide/tall sprites on hitbox, feet on floor."""
    meta = _npc_meta(npc.npc_type)
    iw, ih = npc.image.get_width(), npc.image.get_height()
    if meta:
        pw = meta.get('phys_w', GRID_SIZE)
        ph = meta.get('phys_h', GRID_SIZE)
        off_x = meta.get('off_x', 0)
        off_y = meta.get('off_y', 0)
        d = npc.direction if npc.direction else 1
        if iw != pw or ih != ph:
            x = npc.rect.x + cam_x + (off_x * -d) - iw // 2 + pw // 2
            y = npc.rect.y + cam_y + off_y - ih + ph
            return x, y
        x = npc.rect.x + cam_x + off_x
        y = npc.rect.bottom + cam_y - ih + off_y
        return x, y
    return npc.rect.x + cam_x, npc.rect.bottom + cam_y - ih

def _object_world_rect(obj):
    """World-space bounds for editor hit tests (matches draw anchors)."""
    if isinstance(obj, NPC):
        meta = _npc_meta(obj.npc_type)
        iw, ih = obj.image.get_width(), obj.image.get_height()
        if meta:
            pw = meta.get('phys_w', GRID_SIZE)
            ph = meta.get('phys_h', GRID_SIZE)
            off_x = meta.get('off_x', 0)
            off_y = meta.get('off_y', 0)
            d = obj.direction if obj.direction else 1
            if iw != pw or ih != ph:
                x = obj.rect.x + (off_x * -d) - iw // 2 + pw // 2
                y = obj.rect.y + off_y - ih + ph
                return pygame.Rect(x, y, iw, ih)
            x = obj.rect.x + off_x
            y = obj.rect.bottom - ih + off_y
            return pygame.Rect(x, y, iw, ih)
        return pygame.Rect(obj.rect.x, obj.rect.bottom - ih, iw, ih)
    if isinstance(obj, Tile):
        w = getattr(obj, 'width', GRID_SIZE)
        h = getattr(obj, 'height', GRID_SIZE)
        return pygame.Rect(obj.rect.x, obj.rect.y, w, h)
    if isinstance(obj, BGO):
        iw, ih = obj.image.get_width(), obj.image.get_height()
        return pygame.Rect(obj.rect.x, obj.rect.y, iw, ih)
    return obj.rect.copy()

def _pick_object_at(layer, gx, gy, wx=None, wy=None):
    """SMBX 1.3 editor delete pick: NPC, then block, then BGO (front to back)."""
    for npc in layer.npcs:
        if npc.rect.x == gx and npc.rect.y == gy:
            return npc
    if (gx, gy) in layer.tile_map:
        return layer.tile_map[(gx, gy)]
    for bgo in layer.bgos:
        if bgo.rect.x == gx and bgo.rect.y == gy:
            return bgo
    if wx is None or wy is None:
        return None
    pt = (float(wx), float(wy))
    for npc in list(layer.npcs):
        if _object_world_rect(npc).collidepoint(pt):
            return npc
    for tile in list(layer.tile_map.values()):
        if _object_world_rect(tile).collidepoint(pt):
            return tile
    for bgo in list(layer.bgos):
        if _object_world_rect(bgo).collidepoint(pt):
            return bgo
    return None

def cgi_finish(surf):
    """SMBX 1.3 crisp bevel — keeps colors vivid (no gray MULT wash)."""
    out = surf.copy()
    w, h = out.get_size()
    if w > 2 and h > 2:
        pygame.draw.line(out, (255, 255, 255), (0, 0), (w - 1, 0))
        pygame.draw.line(out, (255, 255, 255), (0, 0), (0, h - 1))
        pygame.draw.line(out, (0, 0, 0), (w - 1, 0), (w - 1, h - 1))
        pygame.draw.line(out, (0, 0, 0), (0, h - 1), (w - 1, h - 1))
    return out

def fit_cgi(surf, w=GRID_SIZE, h=GRID_SIZE):
    sw, sh = surf.get_width(), surf.get_height()
    if sw != w or sh != h:
        surf = pygame.transform.scale(surf, (w, h))
    return cgi_finish(surf)

def _asset(grid, pal, w=GRID_SIZE, h=GRID_SIZE):
    return fit_cgi(px_surf(grid, pal), w, h)

def _mm_pal(theme):
    """SMBX 1.3.0.1 block palettes (overworld / underground / castle)."""
    base = {
        'K': P['black'], 'W': P['white'], 'G': MM_PIPE_C, 'H': MM_PIPE_HI,
        'Y': MM_Q_C, 'O': MM_Q_D, 'B': MM_BRICK_C, 'L': MM_BRICK_D,
    }
    if theme == 'under':
        return {**base,
                'E': (120, 96, 48), 'D': (72, 56, 24),
                'R': (0, 120, 200), 'H': (0, 80, 160),
                'G': (0, 140, 200), 'Y': (255, 200, 80)}
    if theme == 'castle':
        return {**base,
                'E': (148, 148, 168), 'D': (96, 96, 116),
                'R': (180, 180, 200), 'H': (120, 120, 140),
                'G': (80, 80, 100), 'B': (160, 160, 180), 'L': (100, 100, 120),
                'Y': (200, 200, 220), 'O': (160, 160, 180)}
    return {**base,
            'E': MM_EARTH, 'D': MM_EARTH_D,
            'R': MM_GRASS, 'H': MM_GRASS_D}

def asset_theme():
    return {'SMB1': 'over', 'SMB3': 'under', 'SMW': 'over'}.get(current_theme, 'over')

