def _tint_grid(grid, pal, tint):
    p = dict(pal)
    p['E'] = tint
    p['D'] = tuple(max(0, c - 40) for c in tint)
    return _asset(grid, p)

def _slope_grid(left=True, theme='over'):
    g = [list('.' * 16) for _ in range(16)]
    pal = _mm_pal(theme)
    grass_top = theme == 'over'
    for y in range(16):
        for x in range(16):
            inside = (x <= 15 - y) if left else (x >= y)
            if not inside:
                continue
            if grass_top and y < 2:
                g[y][x] = 'R' if (x + y) % 2 == 0 else 'H'
            else:
                g[y][x] = 'E'
    return _asset([''.join(r) for r in g], pal)

def _grass_block_grid():
    rows = []
    for y in range(16):
        row = []
        for x in range(16):
            row.append('R' if (x + y) % 2 == 0 else 'H')
        rows.append(''.join(row))
    return rows

def _cgi_bgo(kind):
    s = pygame.Surface((GRID_SIZE, GRID_SIZE), pygame.SRCALPHA)
    c = get_theme_color('bgo_' + kind if not kind.startswith('bgo_') else kind)
    if kind == 'cloud':
        pygame.draw.ellipse(s, (255, 255, 255), (2, 10, 28, 18))
        pygame.draw.ellipse(s, (240, 248, 255), (0, 14, 14, 14))
        pygame.draw.ellipse(s, (240, 248, 255), (18, 14, 14, 14))
    elif kind == 'bush':
        pygame.draw.ellipse(s, (0, 180, 0), (4, 14, 24, 14))
        pygame.draw.circle(s, (0, 200, 40), (10, 18), 8)
        pygame.draw.circle(s, (0, 200, 40), (22, 18), 8)
    elif kind == 'hill':
        pygame.draw.polygon(s, (80, 200, 80), [(0, 30), (16, 6), (32, 30)])
        pygame.draw.polygon(s, (0, 160, 0), [(0, 30), (16, 6), (32, 30)], 1)
    elif kind == 'tree':
        pygame.draw.rect(s, (120, 72, 24), (14, 22, 4, 10))
        pygame.draw.circle(s, (0, 160, 0), (16, 14), 11)
    elif kind == 'castle':
        pygame.draw.rect(s, (160, 140, 120), (4, 12, 24, 20))
        for bx in (4, 12, 20):
            pygame.draw.rect(s, (120, 100, 80), (bx, 4, 8, 10))
    elif kind == 'waterfall':
        for x in range(6, 26, 4):
            pygame.draw.line(s, (100, 200, 255), (x, 4), (x, 30), 2)
    elif kind == 'sign':
        pygame.draw.rect(s, (120, 72, 24), (14, 18, 4, 14))
        pygame.draw.rect(s, (255, 200, 80), (4, 6, 24, 14))
    elif kind.startswith('fence'):
        fc = (200, 160, 80)
        for x in range(2, 30, 6):
            pygame.draw.rect(s, fc, (x, 8, 4, 22))
        pygame.draw.rect(s, fc, (2, 14, 28, 3))
    else:
        pygame.draw.rect(s, c if c != (128, 128, 128) else (0, 180, 0), (6, 6, 20, 20))
    return cgi_finish(s)

def _cgi_npc_badge(npc_type):
    """Hedgehog Engine-style CGI badge for NPC types without a CHR grid."""
    colors = {
        'lakitu': (0, 200, 80), 'buzzy': (160, 160, 180), 'spiny': (220, 60, 60),
        'cheep': (255, 80, 80), 'blooper': (255, 140, 180), 'thwomp': (140, 140, 160),
        'bowser': (0, 180, 40), 'boo': (255, 255, 255), 'podoboo': (255, 120, 0),
        'piranha_fire': (255, 60, 0), 'rotodisc': (180, 180, 200), 'burner': (255, 140, 0),
        'grinder': (160, 160, 180), 'fishbone': (240, 240, 255), 'dry_bones': (220, 220, 220),
        'bomber_bill': (80, 80, 80), 'bowser_statue': (100, 100, 120),
        'boo_ring': (255, 200, 255), 'skull_platform': (180, 180, 180),
        'bony_beetle': (140, 140, 160), 'cannon': (100, 100, 100),
    }
    c = colors.get(npc_type, (0, 180, 0))
    s = pygame.Surface((GRID_SIZE, GRID_SIZE), pygame.SRCALPHA)
    pygame.draw.rect(s, c, (4, 8, 24, 22), border_radius=4)
    pygame.draw.rect(s, (0, 0, 0), (4, 8, 24, 22), 1, border_radius=4)
    label = npc_type.replace('_', ' ')[:3].upper()
    try:
        f = pygame.font.SysFont('Arial', 9, bold=True)
        t = f.render(label, True, (0, 0, 0) if sum(c) > 400 else (255, 255, 255))
        s.blit(t, t.get_rect(center=(16, 19)))
    except Exception:
        pass
    return cgi_finish(s)

def _bake_nes_npcs(atlas, only=None):
    """CHR fallback bake — Hedgehog Engine grids when SMBX sheet missing."""
    themes = ('over', 'under', 'castle')
    for npc_type, (ga, gb, pal_src) in NES_NPC_DEFS.items():
        if only is not None and npc_type not in only:
            continue
        tall = npc_type in TALL_NPC_TYPES
        for th in themes:
            pal = pal_src(th) if callable(pal_src) else pal_src
            atlas[f'npc_{npc_type}_f0_{th}'] = nes_sprite(ga, pal, tall=tall)
            atlas[f'npc_{npc_type}_f1_{th}'] = (
                nes_sprite(gb, pal, tall=tall) if gb and gb is not ga
                else atlas[f'npc_{npc_type}_f0_{th}']
            )
            for fi in range(2, 8):
                atlas[f'npc_{npc_type}_f{fi}_{th}'] = atlas[f'npc_{npc_type}_f{fi % 2}_{th}']

def _load_smbx_png(b64_dict, type_id):
    """Decode one SMBX 1.3 sheet from an inline base64 dict (FILES=OFF)."""
    try:
        tid = int(type_id)
    except (TypeError, ValueError):
        tid = type_id
    b64 = b64_dict.get(tid)
    if b64 is None and tid is not type_id:
        b64 = b64_dict.get(type_id)
    if not b64:
        return None
    if not isinstance(b64, str):
        b64 = ''.join(b64)
    try:
        img = pygame.image.load(io.BytesIO(base64.b64decode(b64)))
    except (pygame.error, ValueError):
        return None
    try:
        if pygame.display.get_surface() is not None:
            img = img.convert_alpha()
    except pygame.error:
        pass
    return img

def _load_smbx_sheet(type_id):
    return _load_smbx_png(SMBX_NPC_PNG_B64, type_id)

def _crop_smbx_block(sheet, tile_type):
    """Extract one 32×32 SMBX block-{id}.png cell for the editor atlas."""
    w, h = sheet.get_size()
    if tile_type == 'question':
        return fit_cgi(sheet.subsurface((0, 0, 32, 32)).copy())
    if tile_type == 'question_used':
        if w >= 64:
            return fit_cgi(sheet.subsurface((32, 0, 32, 32)).copy())
        return fit_cgi(sheet.subsurface((0, 0, 32, 32)).copy())
    if tile_type == 'pipe_horizontal' and w >= 64:
        return fit_cgi(sheet.subsurface((32, 0, 32, 32)).copy())
    if tile_type == 'slope_left' and w >= 96 and h >= 96:
        return fit_cgi(sheet.subsurface((64, 64, 32, 32)).copy())
    if tile_type in ('water', 'lava') and w >= 64:
        return fit_cgi(sheet.subsurface((0, 0, 32, 32)).copy())
    fw, fh = min(GRID_SIZE, w), min(GRID_SIZE, h)
    return fit_cgi(sheet.subsurface((0, 0, fw, fh)).copy())

def _bake_smbx_blocks(atlas):
    """Bake SMBX 1.3.0.1 block-{id}.png sheets into themed tile keys."""
    if not SMBX_BLOCK_PNG_B64:
        return
    themes = ('over', 'under', 'castle')
    sheets = {}
    for tid in set(TILE_SMBX_IDS.values()):
        sheet = _load_smbx_png(SMBX_BLOCK_PNG_B64, tid)
        if sheet is not None:
            sheets[tid] = sheet
    for tile_type, tid in TILE_SMBX_IDS.items():
        if tile_type == 'coin':
            coin_sheet = sheets.get(10)
            if coin_sheet is not None:
                atlas['coin'] = _crop_smbx_block(coin_sheet, 'coin')
            continue
        sheet = sheets.get(tid)
        if sheet is None:
            continue
        tile_surf = _crop_smbx_block(sheet, tile_type)
        for th in themes:
            atlas[f'{tile_type}_{th}'] = tile_surf
    qsheet = sheets.get(34)
    if qsheet is not None and qsheet.get_width() >= 64:
        used = fit_cgi(qsheet.subsurface((32, 0, 32, 32)).copy())
        for th in themes:
            atlas[f'question_used_{th}'] = used

def _bake_smbx_bgos(atlas):
    """Bake SMBX 1.3.0.1 background-{id}.png into bgo_* keys."""
    if not SMBX_BGO_PNG_B64:
        return
    for bgo_type, tid in BGO_SMBX_IDS.items():
        sheet = _load_smbx_png(SMBX_BGO_PNG_B64, tid)
        if sheet is not None:
            atlas[f'bgo_{bgo_type}'] = sheet

def _bake_smbx_player(atlas):
    """Bake SMBX 1.3.0.1 player-1.png rows into Mario poses."""
    if not SMBX_PLAYER_PNG_B64:
        return
    sheet = _load_smbx_png(SMBX_PLAYER_PNG_B64, 1)
    if sheet is None:
        return
    rows = sheet.get_height() // GRID_SIZE
    for key, row in (('mario_stand', 0), ('mario_walk', 1), ('mario_jump', 3)):
        if row < rows:
            frame = sheet.subsurface((0, row * GRID_SIZE, GRID_SIZE, GRID_SIZE)).copy()
            atlas[key] = fit_cgi(frame)

def _bake_smbx_frame(sheet, gw, gh, row):
    """Extract one SMBX npc-{id}.png row (modGraphics: Frame * NPCHeightGFX)."""
    src_y = row * gh
    if src_y + gh > sheet.get_height():
        return None
    w = min(gw, sheet.get_width())
    frame = sheet.subsurface((0, src_y, w, gh)).copy()
    if frame.get_size() != (gw, gh):
        frame = pygame.transform.scale(frame, (gw, gh))
    return frame

def _bake_smbx_npcs(atlas):
    """Bake SMBX 1.3.0.1 npc-{id}.png sheets — modGraphics.bas row * gfx_h."""
    if not SMBX_NPC_PNG_B64:
        _bake_nes_npcs(atlas)
        return
    sheets = {}
    for tid in set(NPC_SMBX_IDS.values()):
        sheet = _load_smbx_sheet(tid)
        if sheet is not None:
            sheets[tid] = sheet
    baked = set()
    for npc_type, tid in NPC_SMBX_IDS.items():
        meta = _npc_meta(npc_type)
        sheet = sheets.get(tid)
        if not meta or sheet is None:
            continue
        gw, gh = meta.get('gfx_w', 32), meta.get('gfx_h', 32)
        if gh <= 0:
            continue
        rows = sheet.get_height() // gh
        for f in range(rows):
            frame = _bake_smbx_frame(sheet, gw, gh, f)
            if frame is not None:
                atlas[f'npc_{npc_type}_f{f}'] = frame
        if rows > 0:
            baked.add(npc_type)
    missing = [t for t in NPC_SMBX_IDS if t not in baked]
    # Never CHR-fallback koopas — SMBX sheets only or skip
    chr_missing = [t for t in missing if t not in SMBX_KOOPA_TYPES]
    if chr_missing:
        _bake_nes_npcs(atlas, only=chr_missing)
    if FILES_OFF:
        for npc_type in NPC_SMBX_IDS:
            if atlas.get(f'npc_{npc_type}_f0') or atlas.get(f'npc_{npc_type}_f0_over'):
                continue
            badge = _cgi_npc_badge(npc_type)
            for fi in range(8):
                atlas[f'npc_{npc_type}_f{fi}'] = badge
                for th in ('over', 'under', 'castle'):
                    atlas[f'npc_{npc_type}_f{fi}_{th}'] = badge

def _bake_tiles(atlas):
    """Fill any tile keys still missing after SMBX block bake."""
    themes = ('over', 'under', 'castle')
    for th in themes:
        if f'slope_left_{th}' not in atlas:
            atlas[f'slope_left_{th}'] = _slope_grid(True, th)
        if f'slope_right_{th}' not in atlas:
            atlas[f'slope_right_{th}'] = _slope_grid(False, th)
    for tile_type in TILE_SMBX_IDS:
        if tile_type == 'coin':
            continue
        for th in themes:
            key = f'{tile_type}_{th}'
            if key not in atlas:
                atlas[key] = atlas.get(f'ground_{th}')

def _bake_player(atlas):
    """Pre-flip player poses — runtime is ASSETS lookup only."""
    for k in ('mario_stand', 'mario_walk', 'mario_jump'):
        if k in atlas:
            atlas[k + '_l'] = pygame.transform.flip(atlas[k], True, False)

def _ensure_display_for_assets():
    """Pre-baked atlas needs a display format before convert_alpha at startup."""
    if pygame.display.get_surface() is None:
        pygame.display.set_mode((1, 1))

ASSETS = {}

def _npc_asset(npc_type, anim_frame=0, direction=1):
    """SMBX 1.3 decomp sheet frame (FILES=OFF embed) with CHR fallback."""
    key = f'npc_{npc_type}_f{anim_frame}'
    surf = ASSETS.get(key)
    if surf is not None:
        return surf
    th = asset_theme()
    for fi in (anim_frame, 0, 1):
        surf = ASSETS.get(f'npc_{npc_type}_f{fi}_{th}')
        if surf is not None:
            return surf
        surf = ASSETS.get(f'npc_{npc_type}_f{fi}_over')
        if surf is not None:
            return surf
    return ASSETS.get('npc_goomba_f0') or ASSETS.get('npc_goomba_f0_over')

def build_cgi_assets():
    """One-shot pre-render pass — SMBX 1.3 embed bakes over CHR fallbacks (FILES=OFF)."""
    A = {}
    if not FILES_OFF:
        raise RuntimeError(f"{KOOPA_WORKER} requires files = off — gfx is pre-baked at startup")
    for th in ('over', 'under', 'castle'):
        pal = _mm_pal(th)
        used_pal = dict(pal)
        used_pal['E'] = (180, 120, 60) if th == 'over' else (100, 80, 48)
        used_pal['K'] = (120, 80, 40) if th == 'over' else (60, 48, 24)
        A[f'ground_{th}'] = _asset(MM_GROUND, pal)
        A[f'brick_{th}'] = _asset(MM_BRICK, pal)
        A[f'question_{th}'] = _asset(MM_Q, pal)
        A[f'question_used_{th}'] = _asset(MM_Q_USED, used_pal)
        A[f'pipe_vertical_{th}'] = _asset(MM_PIPE_TL, pal)
        A[f'pipe_horizontal_{th}'] = _asset(_flip_h(MM_PIPE_BL), pal)
        A[f'platform_{th}'] = _tint_grid(MM_GROUND, pal, (160, 100, 50))
        A[f'stone_{th}'] = _tint_grid(MM_GROUND, pal, (160, 160, 180))
        A[f'ice_{th}'] = _tint_grid(MM_GROUND, pal, (180, 230, 255))
        A[f'sand_{th}'] = _tint_grid(MM_GROUND, pal, (240, 210, 120))
        A[f'dirt_{th}'] = _tint_grid(MM_GROUND, pal, (160, 100, 50))
        A[f'grass_{th}'] = _asset(_grass_block_grid(), pal)
        A[f'mushroom_platform_{th}'] = _tint_grid(MM_BRICK, pal, (255, 120, 200))
        A[f'pswitch_{th}'] = _asset(MM_Q, {**pal, 'Y': (80, 80, 255), 'O': (40, 40, 200)})
        A[f'bridge_{th}'] = _tint_grid(MM_BRICK, pal, (200, 140, 60))
        A[f'semisolid_{th}'] = _asset(MM_BRICK, {**pal, 'L': (255, 220, 160)})
        A[f'conveyor_left_{th}'] = _asset(MM_BRICK, {**pal, 'L': (180, 180, 200)})
        A[f'conveyor_right_{th}'] = _asset(MM_BRICK, {**pal, 'L': (180, 180, 200)})
    for th in ('over', 'under', 'castle'):
        w = pygame.Surface((GRID_SIZE, GRID_SIZE), pygame.SRCALPHA)
        w.fill((40, 100, 255, 160))
        for i in range(0, GRID_SIZE, 6):
            pygame.draw.arc(w, (120, 200, 255), (i, 18, 8, 6), 0, math.pi, 1)
        A[f'water_{th}'] = cgi_finish(w)
        lv = pygame.Surface((GRID_SIZE, GRID_SIZE), pygame.SRCALPHA)
        lv.fill((255, 100, 0))
        for i in range(0, GRID_SIZE, 5):
            pygame.draw.line(lv, (255, 220, 0), (i, 20), (i + 3, 14), 2)
        A[f'lava_{th}'] = cgi_finish(lv)
    A['coin'] = _asset(COIN_G, {'Y': (255, 200, 0), 'O': (255, 160, 0)})
    A['mario_stand'] = nes_sprite(MARIO_STAND, MARIO_PAL)
    A['mario_walk'] = nes_sprite(MARIO_WALK, MARIO_PAL)
    A['mario_jump'] = nes_sprite(MARIO_JUMP, MARIO_PAL)
    for kind in BGO_SMBX_IDS:
        A[f'bgo_{kind}'] = _cgi_bgo(kind)
    _bake_smbx_blocks(A)
    _bake_smbx_bgos(A)
    _bake_smbx_player(A)
    _bake_smbx_npcs(A)
    _bake_tiles(A)
    _bake_player(A)
    return A

def _tile_asset(tile_type, frame=0):
    """Pre-built tile lookup (FILES=OFF atlas)."""
    th = asset_theme()
    if tile_type == 'coin':
        return ASSETS['coin']
    if tile_type == 'used_block':
        return ASSETS.get(f'question_used_{th}', ASSETS.get(f'ground_{th}'))
    return ASSETS.get(f'{tile_type}_{th}', ASSETS.get(f'ground_{th}'))

def _player_asset(velocity, direction, powerup=0):
    """Pre-built player pose lookup."""
    if velocity.y < -1.5:
        k = 'mario_jump'
    elif abs(velocity.x) > 0.2:
        k = 'mario_walk'
    else:
        k = 'mario_stand'
    if direction < 0:
        k += '_l'
    return ASSETS.get(k, ASSETS['mario_stand'])

_ensure_display_for_assets()
ASSETS = build_cgi_assets()

class GameObject(pygame.sprite.Sprite):
    def __init__(self, x, y, obj_type, layer=0, event_id=-1, flags=0):
        super().__init__()
        self.rect = pygame.Rect(x, y, GRID_SIZE, GRID_SIZE)
        self.layer = layer
        self.obj_type = obj_type
        self.event_id = event_id
        self.flags = flags


class Tile(GameObject):
    def __init__(self, x, y, tile_type, layer=0, event_id=-1, flags=0,
                 event_hit=-1, event_layer_empty=-1, contents=0,
                 contained_npc_id=0, special_data=0, width=GRID_SIZE, height=GRID_SIZE):
        super().__init__(x, y, tile_type, layer, event_id, flags)
        self.tile_type = tile_type
        self.is_solid = self._is_solid()
        self.width = width
        self.height = height
        self.event_hit = event_hit
        self.event_layer_empty = event_layer_empty
        self.contents = contents
        self.contained_npc_id = contained_npc_id
        self.special_data = special_data
        self.update_image()

    def _is_solid(self):
        return self.tile_type not in ['coin', 'water', 'lava']

    def is_semisolid(self):
        return self.tile_type == 'semisolid'

    def update_image(self):
        self.image = _tile_asset(self.tile_type)


class BGO(GameObject):
    def __init__(self, x, y, bgo_type, layer=0, event_id=-1, flags=0,
                 z_layer="Default", sx=64, sy=64):
        super().__init__(x, y, bgo_type, layer, event_id, flags)
        self.bgo_type = bgo_type
        self.z_layer = z_layer
        self.sx = sx
        self.sy = sy
        self.update_image()

    def update_image(self):
        self.image = ASSETS.get(f'bgo_{self.bgo_type}', ASSETS.get('bgo_cloud'))


class NPC(GameObject):
    def __init__(self, x, y, npc_type, layer=0, event_id=-1, flags=0,
                 direction=1, special_data=0, npc_type_mode=0,
                 generic_animation=0, face_direction=1,
                 no_fireball_kill=0, no_iceball_kill=0, no_yoshi_eat=0,
                 is_star=0, is_throwable=0, is_grabable=0, is_bombable=0,
                 is_shell_surfer=0, is_not_moving=0, is_stuck_debris=0,
                 speed=1.0, can_be_eaten_by_plant=0, enable_particle_effect=0,
                 is_base_plate=0, is_tangible=1, attach_surface=0,
                 auto_destroy_timer=-1, event_die=-1, event_talk=-1,
                 event_empty_layer=-1):
        super().__init__(x, y, npc_type, layer, event_id, flags)
        self.npc_type = npc_type
        self.direction = direction
        self.special_data = special_data
        self.npc_type_mode = npc_type_mode
        self.generic_animation = generic_animation
        self.face_direction = face_direction
        self.no_fireball_kill = no_fireball_kill
        self.no_iceball_kill = no_iceball_kill
        self.no_yoshi_eat = no_yoshi_eat
        self.is_star = is_star
        self.is_throwable = is_throwable
        self.is_grabable = is_grabable
        self.is_bombable = is_bombable
        self.is_shell_surfer = is_shell_surfer
        self.is_not_moving = is_not_moving
        self.is_stuck_debris = is_stuck_debris
        self.speed = speed
        self.can_be_eaten_by_plant = can_be_eaten_by_plant
        self.enable_particle_effect = enable_particle_effect
        self.is_base_plate = is_base_plate
        self.is_tangible = is_tangible
        self.attach_surface = attach_surface
        self.auto_destroy_timer = auto_destroy_timer
        self.event_die = event_die
        self.event_talk = event_talk
        self.event_empty_layer = event_empty_layer
        self.velocity = pygame.Vector2(0, 0)
        self.state = 'normal'
        self.shell_moving = False
        self.spawn_x = x
        self.spawn_y = y
        self.on_ground = False
        self.frame = 0
        self.anim_frame = _editor_npc_frame(npc_type, direction)
        self.anim_count = 0
        meta = _npc_meta(npc_type)
        if meta:
            self.rect.width = meta.get('phys_w', GRID_SIZE)
            self.rect.height = meta.get('phys_h', GRID_SIZE)
            spd = meta.get('speed', 1.0)
            if spd > 0:
                self.speed = spd
        self.update_image()

    def update_image(self):
        self.image = _npc_asset(self.npc_type, self.anim_frame, self.direction)

    def update(self, solid_tiles, player, events, npc_group=None):
        algo = _npc_algorithm(self)
        self.on_ground = _npc_on_ground(self, solid_tiles)
        use_gravity = algo not in ('para', 'fly_h', 'podoboo', 'orbit', 'piranha', 'boo')
        if algo in ('cheep', 'blooper'):
            use_gravity = False
        if use_gravity and not self._is_flying_legacy():
            self.velocity.y += NPC_GRAVITY
            self.velocity.y = min(self.velocity.y, TERMINAL_VELOCITY)
        _smbx_npc_ai(self, solid_tiles, player)
        self.rect.x += self.velocity.x
        self._collide(solid_tiles, 'x', events)
        self.rect.y += self.velocity.y
        self.on_ground = _npc_on_ground(self, solid_tiles)
        self._collide(solid_tiles, 'y', events)
        if npc_group is not None:
            _npc_vs_npcs(self, npc_group)
        self.frame += 1
        if _tick_smbx_frames(self):
            self.update_image()

    def _is_flying_legacy(self):
        return _npc_algorithm(self) in ('para', 'fly_h', 'podoboo', 'orbit')

    def _collide(self, tiles, axis, events):
        flipped = False
        for t in tiles:
            if self.rect.colliderect(t.rect):
                if axis == 'x':
                    if self.velocity.x > 0:
                        self.rect.right = t.rect.left
                    else:
                        self.rect.left = t.rect.right
                    self.direction = -self.direction
                    self.velocity.x = _npc_horiz_speed(self)
                    meta = _npc_meta(self.npc_type)
                    if meta and meta.get('frame_style') == 1:
                        self.anim_frame = _editor_npc_frame(self.npc_type, self.direction)
                    else:
                        _clamp_smbx_frame(self)
                    flipped = True
                elif axis == 'y':
                    if not _tile_blocks_upward(t) and self.velocity.y < 0:
                        continue
                    if self.velocity.y > 0:
                        self.rect.bottom = t.rect.top
                    else:
                        self.rect.top = t.rect.bottom
                    self.velocity.y = 0
                if t.tile_type == 'lava':
                    self.kill()
                elif t.tile_type == 'water':
                    self.velocity.y *= 0.5
        if flipped:
            self.update_image()


class Fireball(pygame.sprite.Sprite):
    def __init__(self, x, y, direction):
        super().__init__()
        self.rect = pygame.Rect(x, y, 12, 12)
        self.direction = direction
        self.velocity = pygame.Vector2(direction * 6.0, -2.0)
        self.bounces = 0
        self.life = 0
        self.image = _player_asset(pygame.Vector2(self.velocity.x, 0), direction, 0)
        self.image = pygame.transform.scale(self.image, (12, 12))

    def update(self, solid_tiles, npc_group):
        self.velocity.y = min(self.velocity.y + 0.3, 8.0)
        self.rect.x += self.velocity.x
        self._collide_tiles(solid_tiles, 'x')
        self.rect.y += self.velocity.y
        self._collide_tiles(solid_tiles, 'y')
        for npc in pygame.sprite.spritecollide(self, npc_group, False):
            if npc.is_tangible and not npc.is_star:
                npc.kill()
                self.kill()
                return
        self.life += 1
        if self.life > 120 or self.bounces > 3:
            self.kill()

    def _collide_tiles(self, tiles, axis):
        for t in tiles:
            if self.rect.colliderect(t.rect):
                if axis == 'x':
                    if self.velocity.x > 0:
                        self.rect.right = t.rect.left
                    else:
                        self.rect.left = t.rect.right
                    self.velocity.x *= -1
                    self.direction *= -1
                elif axis == 'y':
                    if self.velocity.y > 0:
                        self.rect.bottom = t.rect.top
                        self.velocity.y = -4.0
                        self.bounces += 1
                    else:
                        self.rect.top = t.rect.bottom
                        self.velocity.y = 0

    def draw(self, surf, camera_offset):
        cx, cy = camera_offset
        surf.blit(self.image, (self.rect.x + cx, self.rect.y + cy))


class Player(pygame.sprite.Sprite):
    def __init__(self, x, y):
        super().__init__()
        self.rect = pygame.Rect(x, y, GRID_SIZE, GRID_SIZE)
        self.direction = 1
        self.velocity = pygame.Vector2(0, 0)
        self.on_ground = False
        self.powerup_state = 0
        self.invincible = 0
        self.star_timer = 0
        self.coins = 0
        self.score = 0
        self.lives = 3
        self.jump_held = False
        self.jump_counter = 0
        self.variable_jump_timer = 0
        self.level_start = (x, y)
        self.anim = 0
        self.fireballs = []
        self.fire_cooldown = 0
        self.update_image()

    def update_image(self):
        if self.star_timer > 0 and (self.star_timer // 6) % 2 == 0:
            self.image = _player_asset(self.velocity, self.direction, 3)
        else:
            self.image = _player_asset(self.velocity, self.direction, self.powerup_state)

    def _spawn_item(self, tile, section):
        contents = getattr(tile, 'contents', 0)
        if tile.tile_type == 'question' or tile.tile_type == 'brick':
            if contents:
                npc_type = {1: 'mushroom', 2: 'flower', 3: 'star', 4: '1up', 5: 'smb3_coin'}.get(contents, 'mushroom')
            else:
                npc_type = 'mushroom'
            new_npc = NPC(tile.rect.x, tile.rect.y - GRID_SIZE, npc_type)
            layer = section.layers[0] if section.layers else None
            if layer:
                layer.npcs.add(new_npc)

    def _die(self, npc_group, section):
        self.lives -= 1
        if self.lives <= 0:
            self.lives = 3
            self.score = 0
            self.coins = 0
        self.rect.topleft = self.level_start
        self.velocity = pygame.Vector2(0, 0)
        self.powerup_state = 0
        self.invincible = 120
        self.star_timer = 0

    def update(self, solid_tiles, npc_group, events, section=None):
        keys = pygame.key.get_pressed()
        run = keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT]

        if self.fire_cooldown > 0:
            self.fire_cooldown -= 1
        if self.powerup_state >= 2 and keys[pygame.K_s] and self.fire_cooldown <= 0:
            fx = self.rect.right if self.direction > 0 else self.rect.left - 12
            fb = Fireball(fx, self.rect.centery - 6, self.direction)
            self.fireballs.append(fb)
            self.fire_cooldown = 15

        for fb in list(self.fireballs):
            fb.update(solid_tiles, npc_group)
            if not fb.alive():
                self.fireballs.remove(fb)

        target = 0.0
        if keys[pygame.K_LEFT] or keys[pygame.K_a]:
            target = -(_smbx_tick(RUN_SPEED) if run else _smbx_tick(WALK_SPEED))
            self.direction = -1
        elif keys[pygame.K_RIGHT] or keys[pygame.K_d]:
            target = (_smbx_tick(RUN_SPEED) if run else _smbx_tick(WALK_SPEED))
            self.direction = 1
        accel = _smbx_tick(SMBX_PHYSICS['player_accel'])
        decel = _smbx_tick(SMBX_PHYSICS['player_decel'])
        if target == 0:
            if self.velocity.x > 0:
                self.velocity.x = max(0.0, self.velocity.x - decel)
            elif self.velocity.x < 0:
                self.velocity.x = min(0.0, self.velocity.x + decel)
        elif self.velocity.x < target:
            self.velocity.x = min(target, self.velocity.x + accel)
        elif self.velocity.x > target:
            self.velocity.x = max(target, self.velocity.x - accel)
        self.velocity.x = max(-SMBX_PHYSICS['player_max_speed'],
                             min(SMBX_PHYSICS['player_max_speed'], self.velocity.x))

        if keys[pygame.K_SPACE]:
            if self.on_ground and self.jump_counter == 0:
                self.velocity.y = _smbx_tick(JUMP_STRENGTH)
                self.jump_counter = JUMP_HOLD_MAX
                self.on_ground = False
            self.jump_held = True
        else:
            if self.jump_held and self.jump_counter > 0:
                self.jump_counter = 0
            self.jump_held = False
            if (self.jump_counter == 0 and self.velocity.y
                    < SMBX_PHYSICS['player_jump_cut_threshold']):
                self.velocity.y += _smbx_tick(JUMP_HOLD_FORCE)
        if self.jump_counter > 0:
            self.jump_counter -= 1

        self.velocity.y = min(self.velocity.y + PLAYER_GRAVITY, TERMINAL_VELOCITY)
        self.rect.x += self.velocity.x
        self._collide(solid_tiles, 'x', events, section)
        self.rect.y += self.velocity.y
        self.on_ground = False
        self._collide(solid_tiles, 'y', events, section)

        for npc in pygame.sprite.spritecollide(self, npc_group, False):
            if not npc.is_tangible:
                continue
            if npc.is_star:
                continue
            meta = _npc_meta(npc.npc_type) or {}
            is_shell = _npc_algorithm(npc) == 'shell' or npc.state == 'shell'
            is_powerup = meta.get('algorithm') == 'powerup' or npc.npc_type in ('mushroom', 'flower', 'star', '1up', 'smb3_coin')

            if self.star_timer > 0:
                npc.kill()
                self.score += 200
                continue

            if is_powerup:
                if npc.npc_type == 'star':
                    self.star_timer = 600
                    self.invincible = 600
                    self.score += 1000
                elif npc.npc_type == '1up':
                    self.lives += 1
                    self.score += 1000
                elif npc.npc_type in ('mushroom', 'smb1_mushroom', 'smw_mushroom'):
                    self.powerup_state = max(self.powerup_state, 1)
                    self.score += 1000
                elif npc.npc_type == 'flower':
                    self.powerup_state = max(self.powerup_state, 2)
                    self.score += 1000
                elif npc.npc_type == 'smb3_coin':
                    self.coins += 1
                    self.score += 200
                npc.kill()
                self.update_image()
                continue

            stomp = self.velocity.y > 0 and self.rect.bottom <= npc.rect.centery + 10
            if stomp and not meta.get('hurts_stomp'):
                if _npc_stomp_resolve(npc):
                    self.velocity.y = SMBX_PHYSICS['player_stomp_bounce']
                    self.score += 100
                    continue
            if is_shell:
                side = abs(self.rect.bottom - npc.rect.bottom) < 20
                if side and not stomp:
                    if not npc.shell_moving:
                        _npc_shell_kick(npc, self)
                        continue
                    if self.invincible <= 0:
                        self._die(npc_group, section)
                    continue
            if stomp and meta.get('hurts_stomp'):
                pass
            elif stomp:
                continue
            if self.invincible <= 0:
                self._die(npc_group, section)

        if self.invincible > 0:
            self.invincible -= 1
        if self.star_timer > 0:
            self.star_timer -= 1
            if self.star_timer <= 0:
                self.invincible = 0
        if self.coins >= 100:
            self.coins -= 100
            self.lives += 1
        self.update_image()

    def _collide(self, tiles, axis, events, section=None):
        for t in tiles:
            if self.rect.colliderect(t.rect):
                if t.tile_type == 'lava':
                    self._die(None, section)
                    return
                if t.tile_type == 'water':
                    self.velocity.y *= 0.5
                if t.tile_type == 'coin':
                    t.kill()
                    self.coins += 1
                    self.score += 200
                    continue
                if t.tile_type == 'pswitch':
                    t.kill()
                    continue
                if t.tile_type in ('question', 'brick') and axis == 'y' and self.velocity.y < 0:
                    if section:
                        self._spawn_item(t, section)
                    if t.tile_type == 'brick':
                        t.kill()
                    else:
                        t.tile_type = 'used_block'
                        t.update_image()
                if axis == 'y' and t.tile_type == 'slope_left' and self.velocity.y >= 0:
                    self.rect.bottom = t.rect.top + (self.rect.right - t.rect.left)
                    self.on_ground = True
                    self.velocity.y = 0
                    continue
                if axis == 'y' and t.tile_type == 'slope_right' and self.velocity.y >= 0:
                    self.rect.bottom = t.rect.top + (t.rect.right - self.rect.left)
                    self.on_ground = True
                    self.velocity.y = 0
                    continue
                if axis == 'y' and not _tile_blocks_upward(t) and self.velocity.y < 0:
                    continue
                if axis == 'x':
                    if self.velocity.x > 0:
                        self.rect.right = t.rect.left
                    else:
                        self.rect.left = t.rect.right
                    self.velocity.x = 0
                elif axis == 'y':
                    if self.velocity.y > 0:
                        self.rect.bottom = t.rect.top
                        self.on_ground = True
                    else:
                        self.rect.top = t.rect.bottom
                    self.velocity.y = 0

    def draw(self, surf, camera_offset):
        if self.invincible > 0 and (self.invincible // 5) % 2 == 0:
            pass
        else:
            surf.blit(self.image, self.rect.move(camera_offset))
        for fb in self.fireballs:
            fb.draw(surf, camera_offset)


class Camera:
    def __init__(self, width, height):
        self.camera = pygame.Rect(0, 0, width, height)
        self.width, self.height = width, height
        self.zoom = 1.0

    def update(self, target):
        x = min(0, max(-(self.width - CANVAS_WIDTH / self.zoom),
                        -target.rect.centerx + (CANVAS_WIDTH // 2) / self.zoom))
        y = min(0, max(-(self.height - CANVAS_HEIGHT / self.zoom),
                        -target.rect.centery + (CANVAS_HEIGHT // 2) / self.zoom))
        self.camera = pygame.Rect(x, y, self.width, self.height)

    def move(self, dx, dy):
        self.camera.x = max(-(self.width - CANVAS_WIDTH / self.zoom), min(0, self.camera.x + dx / self.zoom))
        self.camera.y = max(-(self.height - CANVAS_HEIGHT / self.zoom), min(0, self.camera.y + dy / self.zoom))


class Layer:
    def __init__(self, name="Default", visible=True, locked=False, hidden=0):
        self.name = name
        self.visible = visible
        self.locked = locked
        self.hidden = hidden
        self.tiles = pygame.sprite.Group()
        self.bgos = pygame.sprite.Group()
        self.npcs = pygame.sprite.Group()
        self.tile_map = {}

    def add_tile(self, tile):
        self.tiles.add(tile)
        self.tile_map[(tile.rect.x, tile.rect.y)] = tile

    def remove_tile(self, tile):
        self.tiles.remove(tile)
        self.tile_map.pop((tile.rect.x, tile.rect.y), None)



MW_VAR_NAMES = (
    "score", "lives", "coins", "world", "stage", "time",
    "powerup", "direction", "alt_a", "alt_b", "alt_c",
)


class MarioWorkerVars:
    """Mario Worker Fusion globals (TheMarioVariable recomp)."""

    __slots__ = MW_VAR_NAMES

    def __init__(self, **kw):
        self.score = int(kw.get("score", 0))
        self.lives = int(kw.get("lives", 3))
        self.coins = int(kw.get("coins", 0))
        self.world = int(kw.get("world", 1))
        self.stage = int(kw.get("stage", 1))
        self.time = int(kw.get("time", 400))
        self.powerup = int(kw.get("powerup", 0))
        self.direction = int(kw.get("direction", 1))
        self.alt_a = int(kw.get("alt_a", 0))
        self.alt_b = int(kw.get("alt_b", 0))
        self.alt_c = int(kw.get("alt_c", 0))

    @classmethod
    def defaults(cls):
        return cls()

    def as_dict(self):
        return {name: getattr(self, name) for name in MW_VAR_NAMES}

    @classmethod
    def from_dict(cls, data):
        return cls(**{k: data[k] for k in MW_VAR_NAMES if k in data})

    def pack(self):
        return struct.pack(
            "<" + "i" * len(MW_VAR_NAMES),
            *[getattr(self, name) for name in MW_VAR_NAMES],
        )

    @classmethod
    def unpack(cls, blob):
        need = 4 * len(MW_VAR_NAMES)
        if len(blob) < need:
            blob = blob.ljust(need, b"\x00")
        vals = struct.unpack("<" + "i" * len(MW_VAR_NAMES), blob[:need])
        return cls(**dict(zip(MW_VAR_NAMES, vals)))

    def read_from_level(self, level):
        self.lives = int(getattr(level, "initial_lives", 3))
        self.coins = int(getattr(level, "initial_coins", 0))
        self.time = int(getattr(level, "time_limit", 400))

    def apply_to_level(self, level):
        level.initial_lives = max(0, self.lives)
        level.initial_coins = max(0, self.coins)
        level.time_limit = max(0, self.time)


KEN_MAGIC = b"KEN\x1a"
KEN_VERSION = 1
KEN_FLAG_FILES_OFF = 1


def apply_mw_theme(theme):
    global current_theme, ASSETS
    if theme in themes:
        current_theme = theme
        ASSETS = build_cgi_assets()


def refresh_level_sprites(level):
    section = level.current_section()
    for layer in section.layers:
        for t in layer.tiles:
            t.update_image()
        for b in layer.bgos:
            b.update_image()
        for n in layer.npcs:
            n.update_image()


class Section:
    def __init__(self, width=100, height=30):
        self.width = width * GRID_SIZE
        self.height = height * GRID_SIZE
        self.size_left = 0
        self.size_top = 0
        self.layers = [Layer("Default"), Layer("Destroyed Blocks"), Layer("Spawned NPCs")]
        self.current_layer_idx = 0
        self.bg_color = (92, 148, 252)
        self.bg_type = 0
        self.music = 1
        self.music_file = ""
        self.events = []
        self.warps = []
        self.phys_env_zones = []
        self.background_image = None
        self.start_x = 100
        self.start_y = 500
        self.player_direction = 0
        self.player_effect = 0
        self.rewarp_x = -1
        self.rewarp_y = -1
        self.warp_entrance = 0
        self.warp_exit = 0
        self.locked = False
        self.z_layers = [
            {"name": "Background", "priority": 0},
            {"name": "Default", "priority": 100},
            {"name": "Foreground", "priority": 200},
        ]

    def current_layer(self):
        return self.layers[self.current_layer_idx]

    def layer_by_name(self, name):
        for l in self.layers:
            if l.name == name:
                return l
        return self.layers[0]

    def get_solid_tiles(self):
        return [t for layer in self.layers if layer.visible for t in layer.tiles if t.is_solid]


class Level:
    def __init__(self):
        self.sections = [Section()]
        self.current_section_idx = 0
        self.name = "Untitled"
        self.author = "Unknown"
        self.description = ""
        self.license = ""
        self.website = ""
        self.version = "1.0"
        self.no_background = False
        self.time_limit = 400
        self.level_id = 0
        self.stars = 0
        self.initial_lives = 3
        self.initial_coins = 0
        self.max_coins = 0
        self.max_stars_total = 0
        self.max_stars_world = 0
        self.max_stars_level = 0
        self.no_credit = False
        self.restart_level = False
        self.system_id = 0
        self.hub_world_x = 0
        self.hub_world_y = 0
        self.hub_world_level = ""
        self.hub_world_episode = ""
        self.character_starts = [CharacterStart(i) for i in range(5)]
        self.stars_list = []
        self.generator_must_haves = []
        self.physics = {}
        self.luna_config = {}
        self.mw_globals = MarioWorkerVars.defaults()

    def current_section(self):
        return self.sections[self.current_section_idx]

    def current_layer(self):
        return self.current_section().current_layer()

    def collect_all_layer_names(self):
        names = set()
        for sec in self.sections:
            for layer in sec.layers:
                names.add(layer.name)
        return sorted(names)


# -------------------------
# FILE I/O (SMBX .lvl, .38a, .lvlx, .kengine)
# -------------------------

def _u32(n):
    """Coerce to unsigned 32-bit for struct '<I' (maps -1 → 0xFFFFFFFF)."""
    return int(n) & 0xFFFFFFFF


def _i32_from_u32(n):
    """Interpret packed u32 bits as signed i32 (0xFFFFFFFF → -1)."""
    n = int(n) & 0xFFFFFFFF
    return n - 0x100000000 if n & 0x80000000 else n


def _lvl_bytes(level):
    fd, path = tempfile.mkstemp(suffix=".lvl")
    os.close(fd)
    try:
        write_lvl(path, level)
        with open(path, "rb") as fp:
            return fp.read()
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


def write_kengine(filename, level, theme=None):
    """Write koopa worker .kengine binary (embedded .lvl + Mario Worker globals)."""
    theme = theme or current_theme
    mv = getattr(level, "mw_globals", None)
    if isinstance(mv, dict):
        mv = MarioWorkerVars.from_dict(mv)
    elif not isinstance(mv, MarioWorkerVars):
        mv = MarioWorkerVars()
    mv.read_from_level(level)
    level.mw_globals = mv
    lvl_blob = _lvl_bytes(level)
    meta = {
        "theme": theme,
        "description": level.description,
        "luna_config": level.luna_config,
        "physics": level.physics,
        "python": "3.14",
        "engine": APP_TITLE,
        "the_mario_variable": THEMARIOVARIABLE,
        "mw_globals": mv.as_dict(),
    }
    meta_blob = json.dumps(meta, separators=(",", ":")).encode("utf-8")
    name_b = level.name.encode("utf-8")[:63] + b"\x00"
    name_b = name_b.ljust(64, b"\x00")
    author_b = level.author.encode("utf-8")[:31] + b"\x00"
    author_b = author_b.ljust(32, b"\x00")
    theme_b = theme.encode("utf-8")[:15] + b"\x00"
    theme_b = theme_b.ljust(16, b"\x00")
    flags = KEN_FLAG_FILES_OFF if FILES_OFF else 0
    with open(filename, "wb") as fp:
        fp.write(KEN_MAGIC)
        fp.write(struct.pack("<II", KEN_VERSION, flags))
        fp.write(name_b)
        fp.write(author_b)
        fp.write(theme_b)
        fp.write(mv.pack())
        fp.write(struct.pack("<II", len(lvl_blob), len(meta_blob)))
        fp.write(lvl_blob)
        fp.write(meta_blob)


def read_kengine(filename):
    """Load .kengine — Mario Worker globals + embedded SMBX .lvl payload."""
    level = Level()
    try:
        with open(filename, "rb") as fp:
            magic = fp.read(4)
            if magic not in (KEN_MAGIC, b"KPE\x1a"):
                print("Not a valid .kengine file")
                return level
            version, flags = struct.unpack("<II", fp.read(8))
            if version > KEN_VERSION:
                print(f"Unsupported .kengine version {version}")
            name = fp.read(64).split(b"\x00")[0].decode("utf-8", errors="ignore")
            author = fp.read(32).split(b"\x00")[0].decode("utf-8", errors="ignore")
            theme = fp.read(16).split(b"\x00")[0].decode("utf-8", errors="ignore") or "SMB1"
            mv = MarioWorkerVars.unpack(fp.read(4 * len(MW_VAR_NAMES)))
            lvl_len, meta_len = struct.unpack("<II", fp.read(8))
            lvl_blob = fp.read(lvl_len)
            meta_blob = fp.read(meta_len)
        fd, path = tempfile.mkstemp(suffix=".lvl")
        os.close(fd)
        try:
            with open(path, "wb") as fp:
                fp.write(lvl_blob)
            level = read_lvl(path)
        finally:
            try:
                os.remove(path)
            except OSError:
                pass
        if name:
            level.name = name
        if author:
            level.author = author
        level.mw_globals = mv
        mv.apply_to_level(level)
        if meta_blob:
            try:
                meta = json.loads(meta_blob.decode("utf-8"))
                level.description = meta.get("description", level.description)
                level.luna_config = meta.get("luna_config", level.luna_config)
                level.physics = meta.get("physics", level.physics)
                theme = meta.get("theme", theme)
                if "mw_globals" in meta:
                    level.mw_globals = MarioWorkerVars.from_dict(meta["mw_globals"])
                    level.mw_globals.apply_to_level(level)
            except (json.JSONDecodeError, UnicodeDecodeError, TypeError, ValueError):
                pass
        apply_mw_theme(theme)
        refresh_level_sprites(level)
        if flags & KEN_FLAG_FILES_OFF and not FILES_OFF:
            print(".kengine was saved with files=off embed")
    except Exception as e:
        print("Load error:", e)
    return level


def read_lvl(filename):
    level = Level()
    try:
        with open(filename, 'rb') as f:
            magic = f.read(4)
            if magic != b'LVL\x1a':
                print("Not a valid SMBX level file")
                return level
            version = struct.unpack('<I', f.read(4))[0]
            level.name = f.read(32).decode('utf-8', errors='ignore').strip('\x00')
            level.author = f.read(32).decode('utf-8', errors='ignore').strip('\x00')
            level.time_limit = struct.unpack('<I', f.read(4))[0]
            level.stars = struct.unpack('<I', f.read(4))[0]
            flags = struct.unpack('<I', f.read(4))[0]
            level.no_background = bool(flags & 1)
            f.read(128 - 4 - 4 - 32 - 32 - 4 - 4 - 4)

            num_sections = struct.unpack('<I', f.read(4))[0]
            level.sections = []
            for s in range(num_sections):
                section = Section()
                section.width = struct.unpack('<I', f.read(4))[0]
                section.height = struct.unpack('<I', f.read(4))[0]
                bg_r, bg_g, bg_b = struct.unpack('<BBB', f.read(3))
                section.bg_color = (bg_r, bg_g, bg_b)
                f.read(1)  # padding
                section.start_x = struct.unpack('<I', f.read(4))[0]
                section.start_y = struct.unpack('<I', f.read(4))[0]
                section.music = struct.unpack('<I', f.read(4))[0]

                num_blocks = struct.unpack('<I', f.read(4))[0]
                for _ in range(num_blocks):
                    x, y, type_id, layer, event_id, flags = struct.unpack('<IIIIII', f.read(24))
                    x, y, event_id = _i32_from_u32(x), _i32_from_u32(y), _i32_from_u32(event_id)
                    if type_id in TILE_ID_TO_NAME:
                        tile = Tile(x, y, TILE_ID_TO_NAME[type_id], layer, event_id, flags)
                        while len(section.layers) <= layer:
                            section.layers.append(Layer(f"Layer {len(section.layers)+1}"))
                        section.layers[layer].add_tile(tile)

                num_bgos = struct.unpack('<I', f.read(4))[0]
                for _ in range(num_bgos):
                    x, y, type_id, layer, flags = struct.unpack('<IIIII', f.read(20))
                    x, y = _i32_from_u32(x), _i32_from_u32(y)
                    if type_id in BGO_ID_TO_NAME:
                        bgo = BGO(x, y, BGO_ID_TO_NAME[type_id], layer, flags=flags)
                        while len(section.layers) <= layer:
                            section.layers.append(Layer(f"Layer {len(section.layers)+1}"))
                        section.layers[layer].bgos.add(bgo)

                num_npcs = struct.unpack('<I', f.read(4))[0]
                for _ in range(num_npcs):
                    x, y, type_id, layer, event_id, flags, direction, special = struct.unpack('<IIIIIIII', f.read(32))
                    x, y, event_id = _i32_from_u32(x), _i32_from_u32(y), _i32_from_u32(event_id)
                    special = _i32_from_u32(special)
                    if type_id in NPC_ID_TO_NAME:
                        npc = NPC(x, y, NPC_ID_TO_NAME[type_id], layer, event_id, flags,
                                  direction=1 if direction else -1, special_data=special)
                        while len(section.layers) <= layer:
                            section.layers.append(Layer(f"Layer {len(section.layers)+1}"))
                        section.layers[layer].npcs.add(npc)

                num_warps = struct.unpack('<I', f.read(4))[0]
                for _ in range(num_warps):
                    # Read warp data (64 bytes) - we skip for now
                    f.read(64)

                num_events = struct.unpack('<I', f.read(4))[0]
                for _ in range(num_events):
                    name_len = struct.unpack('<B', f.read(1))[0]
                    name = f.read(name_len).decode('utf-8')
                    trigger = struct.unpack('<I', f.read(4))[0]
                    action_count = struct.unpack('<I', f.read(4))[0]
                    for _ in range(action_count):
                        f.read(12)
                    section.events.append(Event(name, str(trigger), [], eid=len(section.events)))

                level.sections.append(section)
    except Exception as e:
        print("Load error:", e)
    return level


def write_lvl(filename, level):
    with open(filename, 'wb') as f:
        f.write(b'LVL\x1a')
        f.write(struct.pack('<I', 1))
        name_bytes = level.name.encode('utf-8')[:31] + b'\x00'
        f.write(name_bytes.ljust(32, b'\x00'))
        author_bytes = level.author.encode('utf-8')[:31] + b'\x00'
        f.write(author_bytes.ljust(32, b'\x00'))
        f.write(struct.pack('<I', _u32(level.time_limit)))
        f.write(struct.pack('<I', _u32(level.stars)))
        flags = (1 if level.no_background else 0)
        f.write(struct.pack('<I', _u32(flags)))
        f.write(b'\x00' * (128 - f.tell()))

        f.write(struct.pack('<I', _u32(len(level.sections))))
        for section in level.sections:
            f.write(struct.pack('<I', _u32(section.width)))
            f.write(struct.pack('<I', _u32(section.height)))
            f.write(struct.pack('<BBB', *section.bg_color[:3]))
            f.write(b'\x00')
            f.write(struct.pack('<I', _u32(section.start_x)))
            f.write(struct.pack('<I', _u32(section.start_y)))
            f.write(struct.pack('<I', _u32(section.music)))

            blocks = []
            for li, layer in enumerate(section.layers):
                for t in layer.tiles:
                    type_id = TILE_SMBX_IDS.get(t.tile_type, 1)
                    event_id = t.event_id if hasattr(t, 'event_id') else -1
                    flags = t.flags if hasattr(t, 'flags') else 0
                    blocks.append((_u32(t.rect.x), _u32(t.rect.y), _u32(type_id),
                                   _u32(li), _u32(event_id), _u32(flags)))
            f.write(struct.pack('<I', _u32(len(blocks))))
            for b in blocks:
                f.write(struct.pack('<IIIIII', *b))

            bgos = []
            for li, layer in enumerate(section.layers):
                for b in layer.bgos:
                    type_id = BGO_SMBX_IDS.get(b.bgo_type, 5)
                    flags = b.flags if hasattr(b, 'flags') else 0
                    bgos.append((_u32(b.rect.x), _u32(b.rect.y), _u32(type_id),
                                 _u32(li), _u32(flags)))
            f.write(struct.pack('<I', _u32(len(bgos))))
            for bg in bgos:
                f.write(struct.pack('<IIIII', *bg))

            npcs = []
            for li, layer in enumerate(section.layers):
                for n in layer.npcs:
                    type_id = NPC_SMBX_IDS.get(n.npc_type, 1)
                    event_id = n.event_id if hasattr(n, 'event_id') else -1
                    flags = n.flags if hasattr(n, 'flags') else 0
                    direction = 1 if n.direction > 0 else 0
                    special = n.special_data if hasattr(n, 'special_data') else 0
                    npcs.append((_u32(n.rect.x), _u32(n.rect.y), _u32(type_id),
                                 _u32(li), _u32(event_id), _u32(flags),
                                 _u32(direction), _u32(special)))
            f.write(struct.pack('<I', _u32(len(npcs))))
            for n in npcs:
                f.write(struct.pack('<IIIIIIII', *n))

            f.write(struct.pack('<I', _u32(len(section.warps))))
            for warp in section.warps:
                f.write(b'\x00' * 64)

            f.write(struct.pack('<I', _u32(len(section.events))))
            for event in section.events:
                name_bytes = event.name.encode('utf-8')
                f.write(struct.pack('<B', len(name_bytes)))
                f.write(name_bytes)
                f.write(struct.pack('<I', 0))
                f.write(struct.pack('<I', 0))


def read_38a(filename):
    temp_dir = tempfile.mkdtemp(prefix="smbx38a_")
    try:
        with zipfile.ZipFile(filename, "r") as zf:
            zf.extractall(temp_dir)

        level_path = os.path.join(temp_dir, "level.lvl")
        if not os.path.exists(level_path):
            for root, _dirs, files in os.walk(temp_dir):
                if "level.lvl" in files:
                    level_path = os.path.join(root, "level.lvl")
                    break
            else:
                raise FileNotFoundError("No level.lvl found inside .38a archive")

        level = read_lvl(level_path)
        level.luna_config = {}
        base = os.path.dirname(level_path)

        for key, fname in [
            ("layers", "layers.txt"),
            ("events", "events.txt"),
            ("lunadll", "lunadll.txt"),
            ("warps", "warp.txt"),
            ("sounds", "sound.txt"),
            ("settings", "settings.txt"),
        ]:
            p = os.path.join(base, fname)
            if os.path.exists(p):
                with open(p, "r", encoding="utf-8", errors="replace") as fp:
                    level.luna_config[key] = fp.read()

        known = {
            "level.lvl",
            "layers.txt",
            "events.txt",
            "lunadll.txt",
            "warp.txt",
            "sound.txt",
            "settings.txt",
        }
        other = {}
        for walk_root, _dirs, files in os.walk(temp_dir):
            for fn in files:
                if fn in known:
                    continue
                full = os.path.join(walk_root, fn)
                arcname = os.path.relpath(full, temp_dir).replace("\\", "/")
                with open(full, "rb") as fp:
                    other[arcname] = fp.read()
        level.luna_config["other_files"] = other
        return level
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def write_38a(filename, level):
    temp_dir = tempfile.mkdtemp(prefix="smbx38a_")
    try:
        write_lvl(os.path.join(temp_dir, "level.lvl"), level)
        cfg = getattr(level, "luna_config", {}) or {}
        for key, fname in [
            ("layers", "layers.txt"),
            ("events", "events.txt"),
            ("lunadll", "lunadll.txt"),
            ("warps", "warp.txt"),
            ("sounds", "sound.txt"),
            ("settings", "settings.txt"),
        ]:
            if key in cfg:
                with open(os.path.join(temp_dir, fname), "w", encoding="utf-8") as fp:
                    fp.write(cfg[key])

        for relpath, content in cfg.get("other_files", {}).items():
            full = os.path.join(temp_dir, relpath.replace("\\", "/"))
            parent = os.path.dirname(full)
            if parent:
                os.makedirs(parent, exist_ok=True)
            with open(full, "wb") as fp:
                fp.write(content)

        with zipfile.ZipFile(filename, "w", zipfile.ZIP_DEFLATED) as zf:
            for walk_root, _dirs, files in os.walk(temp_dir):
                for fn in files:
                    full = os.path.join(walk_root, fn)
                    zf.write(full, os.path.relpath(full, temp_dir))
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def _lvlx_int(el, attr, default=0):
    try:
        return int(el.get(attr, default))
    except (TypeError, ValueError):
        return default


def read_lvlx(filename):
    level = Level()
    try:
        tree = ET.parse(filename)
        root = tree.getroot()

        head = root.find("head")
        if head is not None:
            t = head.findtext("title")
            if t is not None:
                level.name = t
            a = head.findtext("author")
            if a is not None:
                level.author = a
            timer_el = head.find("timer")
            level.time_limit = _lvlx_int(timer_el or ET.Element("x"), "value", 300)
            stars_el = head.find("stars")
            level.stars = _lvlx_int(stars_el or ET.Element("x"), "value", 0)

        level.sections = []
        for sec_el in root.findall("section"):
            sec = Section()
            sec.width = _lvlx_int(sec_el, "size_right", 3200)
            sec.height = _lvlx_int(sec_el, "size_bottom", 960)
            sec.music = _lvlx_int(sec_el, "music_id", 1)
            sec.bg_type = _lvlx_int(sec_el, "background_id", _lvlx_int(sec_el, "background2_id", 0))
            sec.bg_color = (
                _lvlx_int(sec_el, "bgcolor_r", 92),
                _lvlx_int(sec_el, "bgcolor_g", 148),
                _lvlx_int(sec_el, "bgcolor_b", 252),
            )

            for bl in sec_el.findall("block"):
                tid = _lvlx_int(bl, "id")
                x = (_lvlx_int(bl, "x") // GRID_SIZE) * GRID_SIZE
                y = (_lvlx_int(bl, "y") // GRID_SIZE) * GRID_SIZE
                li = _lvlx_int(bl, "layer", 0)
                eid = _lvlx_int(bl, "event_destroy", -1)
                fl = _lvlx_int(bl, "invisible", 0)
                if tid in TILE_ID_TO_NAME:
                    while len(sec.layers) <= li:
                        sec.layers.append(Layer(f"Layer {len(sec.layers)+1}"))
                    sec.layers[li].add_tile(
                        Tile(x, y, TILE_ID_TO_NAME[tid], layer=li, event_id=eid, flags=fl)
                    )

            for bg in sec_el.findall("bgo"):
                tid = _lvlx_int(bg, "id")
                x = (_lvlx_int(bg, "x") // GRID_SIZE) * GRID_SIZE
                y = (_lvlx_int(bg, "y") // GRID_SIZE) * GRID_SIZE
                li = _lvlx_int(bg, "layer", 0)
                if tid in BGO_ID_TO_NAME:
                    while len(sec.layers) <= li:
                        sec.layers.append(Layer(f"Layer {len(sec.layers)+1}"))
                    sec.layers[li].bgos.add(
                        BGO(x, y, BGO_ID_TO_NAME[tid], layer=li, flags=0)
                    )

            for npc_el in sec_el.findall("npc"):
                tid = _lvlx_int(npc_el, "id")
                x = (_lvlx_int(npc_el, "x") // GRID_SIZE) * GRID_SIZE
                y = (_lvlx_int(npc_el, "y") // GRID_SIZE) * GRID_SIZE
                li = _lvlx_int(npc_el, "layer", 0)
                dr = _lvlx_int(npc_el, "direction", 1)
                sp = _lvlx_int(npc_el, "special_data", 0)
                eid = _lvlx_int(npc_el, "event_activate", -1)
                if tid in NPC_ID_TO_NAME or tid in SMBX_NPC_BY_ID:
                    npc_name = NPC_ID_TO_NAME.get(tid) or SMBX_NPC_BY_ID[tid].get('name', f'npc_{tid}')
                    while len(sec.layers) <= li:
                        sec.layers.append(Layer(f"Layer {len(sec.layers)+1}"))
                    face = 1 if dr > 0 else -1
                    sec.layers[li].npcs.add(
                        NPC(
                            x,
                            y,
                            npc_name,
                            layer=li,
                            event_id=eid,
                            flags=0,
                            direction=face,
                            special_data=sp,
                        )
                    )

            for _door in sec_el.findall("door"):
                sec.warps.append(Warp())

            for ev_el in sec_el.findall("event"):
                name = ev_el.get("name", "")
                trig = _lvlx_int(ev_el, "trigger", 0)
                sec.events.append(Event(name, str(trig), [], eid=len(sec.events)))

            level.sections.append(sec)

        if not level.sections:
            level.sections = [Section()]

        sp_el = root.find(".//player_point")
        if sp_el is not None and level.sections:
            level.sections[0].start_x = _lvlx_int(sp_el, "x", level.sections[0].start_x)
            level.sections[0].start_y = _lvlx_int(sp_el, "y", level.sections[0].start_y)
    except Exception as e:
        print("LVLX load error:", e)
    return level


def write_lvlx(filename, level):
    sx, sy = 100, 500
    if level.sections:
        sx = level.sections[0].start_x
        sy = level.sections[0].start_y

    xml_root = ET.Element("root")
    xml_root.set("type", "LevelFile")
    xml_root.set("fileformat", "LVLX")
    xml_root.set("format_version", "67")

    head = ET.SubElement(xml_root, "head")
    ET.SubElement(head, "title").text = level.name
    ET.SubElement(head, "author").text = level.author
    timer = ET.SubElement(head, "timer")
    timer.set("value", str(level.time_limit))
    stars = ET.SubElement(head, "stars")
    stars.set("value", str(level.stars))

    sp = ET.SubElement(xml_root, "player_point")
    sp.set("x", str(sx))
    sp.set("y", str(sy))

    for si, sec in enumerate(level.sections):
        sec_el = ET.SubElement(xml_root, "section")
        sec_el.set("id", str(si))
        sec_el.set("size_right", str(sec.width))
        sec_el.set("size_bottom", str(sec.height))
        sec_el.set("music_id", str(sec.music))
        sec_el.set("background_id", str(int(getattr(sec, "bg_type", 0) or 0)))
        sec_el.set("bgcolor_r", str(sec.bg_color[0]))
        sec_el.set("bgcolor_g", str(sec.bg_color[1]))
        sec_el.set("bgcolor_b", str(sec.bg_color[2]))

        for li, layer in enumerate(sec.layers):
            for tile in layer.tiles:
                bl = ET.SubElement(sec_el, "block")
                bl.set("id", str(TILE_SMBX_IDS.get(tile.tile_type, 1)))
                bl.set("x", str(tile.rect.x))
                bl.set("y", str(tile.rect.y))
                bl.set("layer", str(li))
                bl.set("event_destroy", str(tile.event_id))
                bl.set("invisible", str(tile.flags))

            for bgo in layer.bgos:
                bg = ET.SubElement(sec_el, "bgo")
                bg.set("id", str(BGO_SMBX_IDS.get(bgo.bgo_type, 5)))
                bg.set("x", str(bgo.rect.x))
                bg.set("y", str(bgo.rect.y))
                bg.set("layer", str(li))

            for npc in layer.npcs:
                ne = ET.SubElement(sec_el, "npc")
                ne.set("id", str(NPC_SMBX_IDS.get(npc.npc_type, 1)))
                ne.set("x", str(npc.rect.x))
                ne.set("y", str(npc.rect.y))
                ne.set("layer", str(li))
                ne.set("direction", str(npc.direction))
                ne.set("special_data", str(npc.special_data))
                ne.set("event_activate", str(npc.event_id))

        for _warp in sec.warps:
            ET.SubElement(sec_el, "door")

        for ev in sec.events:
            ev_el = ET.SubElement(sec_el, "event")
            ev_el.set("name", ev.name)
            ev_el.set("trigger", str(ev.trigger))

    tree = ET.ElementTree(xml_root)
    ET.indent(tree, space="  ")
    tree.write(filename, encoding="utf-8", xml_declaration=True)


def detect_format(filename):
    ext = os.path.splitext(filename)[1].lower()
    if ext in (".kengine", ".kpengine"):
        return "kengine"
    if ext == ".38a":
        return "38a"
    if ext == ".lvlx":
        return "lvlx"
    try:
        with open(filename, "rb") as f:
            magic = f.read(4)
            if magic in (KEN_MAGIC, b"KPE\x1a"):
                return "kengine"
            if magic == b"LVL\x1a":
                return "lvl"
            f.seek(0)
            if f.read(2) == b"PK":
                return "38a"
            f.seek(0)
            chunk = f.read(256).lstrip()
            if chunk.startswith(b"<?xml") or chunk.startswith(b"<"):
                return "lvlx"
    except OSError:
        pass
    return "unknown"


def smart_read(filename):
    fmt = detect_format(filename)
    try:
        if fmt == "38a":
            return read_38a(filename)
        if fmt == "kengine":
            return read_kengine(filename)
        if fmt == "lvlx":
            return read_lvlx(filename)
        if fmt == "lvl":
            return read_lvl(filename)
        with open(filename, "rb") as f:
            if f.read(2) == b"PK":
                return read_38a(filename)
    except Exception as e:
        print("Load error:", e)
    return read_lvl(filename)


def smart_write(filename, level):
    ext = os.path.splitext(filename)[1].lower()
    if ext in (".kengine", ".kpengine"):
        write_kengine(filename, level)
    elif ext == ".lvlx":
        write_lvlx(filename, level)
    elif ext == ".38a":
        write_38a(filename, level)
    else:
        write_lvl(filename, level)


# -------------------------
# MENU SYSTEM
# -------------------------
class MenuItem:
    def __init__(self, label, callback=None, shortcut="", checkable=False, checked=False, separator=False):
        self.label = label
        self.callback = callback
        self.shortcut = shortcut
        self.checkable = checkable
        self.checked = checked
        self.separator = separator
        self.enabled = True


class DropMenu:
    ITEM_H = 18
    PAD = 6
    def __init__(self, items):
        self.items = items
        self.hovered = -1
        w = max((FONT_SMALL.size(i.label+("  "+i.shortcut if i.shortcut else ""))[0]+30)
                for i in items if not i.separator)
        self.w = max(140, w)
        self.h = sum(6 if i.separator else self.ITEM_H for i in items) + self.PAD*2

    def draw(self, surf, x, y):
        r = pygame.Rect(x, y, self.w, self.h)
        pygame.draw.rect(surf, SYS_BTN_FACE, r)
        draw_edge(surf, r, raised=True)
        cy = y + self.PAD
        for i, item in enumerate(self.items):
            if item.separator:
                pygame.draw.line(surf, SYS_BTN_DARK, (x+4, cy+3), (x+self.w-4, cy+3))
                cy += 6
                continue
            ir = pygame.Rect(x+2, cy, self.w-4, self.ITEM_H)
            if i == self.hovered and item.enabled:
                pygame.draw.rect(surf, SYS_HIGHLIGHT, ir)
            col = WHITE if i==self.hovered and item.enabled else (GRAY if not item.enabled else SYS_TEXT)
            if item.checkable:
                ch_col = col
                draw_text(surf, "✓" if item.checked else " ", (x+8, cy+2), ch_col, FONT_SMALL)
            draw_text(surf, item.label, (x+22, cy+2), col, FONT_SMALL)
            if item.shortcut:
                sw = FONT_SMALL.size(item.shortcut)[0]
                draw_text(surf, item.shortcut, (x+self.w-sw-6, cy+2), col, FONT_SMALL)
            cy += self.ITEM_H

    def hit_item(self, pos, ox, oy):
        cy = oy + self.PAD
        for i, item in enumerate(self.items):
            if item.separator:
                cy += 6
                continue
            ir = pygame.Rect(ox+2, cy, self.w-4, self.ITEM_H)
            if ir.collidepoint(pos):
                return i
            cy += self.ITEM_H
        return -1

    def update_hover(self, pos, ox, oy):
        self.hovered = self.hit_item(pos, ox, oy)


class MenuBar:
    BAR_H = MENU_HEIGHT
    def __init__(self, menus_def):
        self.menus = []
        self.open_idx = -1
        x = 4
        for label, items in menus_def:
            w = FONT_MENU.size(label)[0] + 14
            dm = DropMenu(items)
            self.menus.append([label, x, w, dm])
            x += w

    def handle_event(self, event):
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if my < self.BAR_H:
                for i, (lbl, bx, bw, dm) in enumerate(self.menus):
                    if bx <= mx < bx+bw:
                        self.open_idx = -1 if self.open_idx == i else i
                        return True
            elif self.open_idx >= 0:
                lbl, bx, bw, dm = self.menus[self.open_idx]
                idx = dm.hit_item(event.pos, bx, self.BAR_H)
                if idx >= 0:
                    item = dm.items[idx]
                    if item.enabled and item.callback:
                        item.callback()
                        if item.checkable:
                            item.checked = not item.checked
                self.open_idx = -1
                return True
            else:
                self.open_idx = -1
        if event.type == pygame.MOUSEMOTION and self.open_idx >= 0:
            lbl, bx, bw, dm = self.menus[self.open_idx]
            dm.update_hover(event.pos, bx, self.BAR_H)
            for i, (l2, bx2, bw2, dm2) in enumerate(self.menus):
                if bx2 <= event.pos[0] < bx2+bw2 and event.pos[1] < self.BAR_H:
                    self.open_idx = i
        if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
            self.open_idx = -1
        return False

    def draw(self, surf):
        pygame.draw.rect(surf, SYS_BTN_FACE, (0,0,WINDOW_WIDTH,self.BAR_H))
        pygame.draw.line(surf, SYS_BTN_DARK, (0,self.BAR_H-1), (WINDOW_WIDTH,self.BAR_H-1))
        for i, (lbl, bx, bw, dm) in enumerate(self.menus):
            r = pygame.Rect(bx, 1, bw, self.BAR_H-2)
            if i == self.open_idx:
                pygame.draw.rect(surf, SYS_HIGHLIGHT, r)
                draw_text(surf, lbl, (bx+7, 3), WHITE, FONT_MENU)
            else:
                draw_text(surf, lbl, (bx+7, 3), SYS_TEXT, FONT_MENU)
        if self.open_idx >= 0:
            lbl, bx, bw, dm = self.menus[self.open_idx]
            dm.draw(surf, bx, self.BAR_H)


# -------------------------
# TOOLBAR BUTTON
# -------------------------
class ToolbarButton:
    def __init__(self, rect, icon_key, callback=None, tooltip="", toggle=False):
        self.rect = pygame.Rect(rect)
        self.icon_key = icon_key
        self.callback = callback
        self.tooltip = tooltip
        self.hovered = False
        self.pressed = False
        self.toggle = toggle
        self.active = False

    def handle_event(self, event):
        if event.type == pygame.MOUSEMOTION:
            self.hovered = self.rect.collidepoint(event.pos)
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if self.rect.collidepoint(event.pos):
                self.pressed = True
                return True
        if event.type == pygame.MOUSEBUTTONUP and event.button == 1:
            if self.pressed and self.rect.collidepoint(event.pos) and self.callback:
                if self.toggle:
                    self.active = not self.active
                self.callback()
            self.pressed = False
        return False

    def draw(self, surf):
        sunken = self.pressed or (self.toggle and self.active)
        if sunken:
            pygame.draw.rect(surf, SYS_BTN_FACE, self.rect)
            pygame.draw.line(surf, SYS_BTN_DARK, self.rect.topleft, self.rect.topright)
            pygame.draw.line(surf, SYS_BTN_DARK, self.rect.topleft, self.rect.bottomleft)
        elif self.hovered:
            pygame.draw.rect(surf, SYS_BTN_FACE, self.rect)
            pygame.draw.line(surf, SYS_BTN_LIGHT, self.rect.topleft, self.rect.topright)
            pygame.draw.line(surf, SYS_BTN_LIGHT, self.rect.topleft, self.rect.bottomleft)
            pygame.draw.line(surf, SYS_BTN_DARK, self.rect.bottomleft, self.rect.bottomright)
            pygame.draw.line(surf, SYS_BTN_DARK, self.rect.topright, self.rect.bottomright)
        else:
            pygame.draw.rect(surf, SYS_BTN_FACE, self.rect)
        fn = ICON_FNS.get(self.icon_key)
        if fn:
            off = (1,1) if sunken else (0,0)
            fn(surf, self.rect.move(off[0], off[1]))


# -------------------------
# SIDEBAR
# -------------------------
class Sidebar:
    def __init__(self):
        self.rect = pygame.Rect(0, CANVAS_Y, SIDEBAR_WIDTH, CANVAS_HEIGHT)
        self.categories = ["Blocks", "Scenery", "Enemies", "Layers"]
        self._cat_map = {"Blocks": "Tiles", "Scenery": "BGOs", "Enemies": "NPCs", "Layers": "Layers"}
        self.current_category = "Blocks"
        self.items = {"Tiles": list(TILE_SMBX_IDS.keys()),
                      "BGOs": list(BGO_SMBX_IDS.keys()),
                      "NPCs": EDITOR_NPC_TYPES,
                      "Layers": []}
        self.selected_item = 'ground'
        self.tab_h = 18
        self.title_h = 16

    def _internal_cat(self):
        return self._cat_map.get(self.current_category, self.current_category)

    def draw(self, surf, level):
        pygame.draw.rect(surf, SYS_BTN_FACE, self.rect)
        draw_edge(surf, self.rect, raised=False)
        tr = pygame.Rect(self.rect.x + 2, self.rect.y + 2, self.rect.width - 4, self.title_h)
        pygame.draw.rect(surf, MW_TITLE_RED, tr)
        draw_text(surf, self.current_category, (tr.x + 4, tr.y + 1), WHITE, FONT_SMALL)
        tab_y = self.rect.y + self.title_h + 2
        tab_w = self.rect.width // len(self.categories)
        for i, cat in enumerate(self.categories):
            r = pygame.Rect(self.rect.x + 2 + i * tab_w, tab_y, tab_w - 2, self.tab_h)
            sel = (cat == self.current_category)
            pygame.draw.rect(surf, SYS_WINDOW if sel else SYS_BTN_FACE, r)
            draw_edge(surf, r, raised=not sel)
            draw_text(surf, cat[:3], r.center, SYS_TEXT, FONT_SMALL, True)
        content = pygame.Rect(self.rect.x + 2, tab_y + self.tab_h, self.rect.width - 4,
                              self.rect.height - self.title_h - self.tab_h - 4)
        pygame.draw.rect(surf, SYS_WINDOW, content)
        if self._internal_cat() == "Layers":
            self._draw_layers(surf, content, level)
        else:
            self._draw_items(surf, content)

    def _draw_items(self, surf, area):
        items = self.items[self._internal_cat()]
        cols = 4
        for i, item in enumerate(items):
            r = pygame.Rect(area.x + 4 + (i % cols) * 38, area.y + 4 + (i // cols) * 38, 32, 32)
            if not area.contains(r):
                continue
            if item == self.selected_item:
                pygame.draw.rect(surf, SYS_HIGHLIGHT2, r.inflate(4, 4))
            preview = pygame.Surface((32, 32), pygame.SRCALPHA)
            cat = self._internal_cat()
            if cat == "Tiles":
                obj = Tile(0, 0, item)
            elif cat == "BGOs":
                obj = BGO(0, 0, item)
            else:
                obj = NPC(0, 0, item)
            py = max(0, 32 - obj.image.get_height())
            preview.blit(obj.image, (0, py))
            surf.blit(preview, r)

    def _draw_layers(self, surf, area, level):
        y = area.y+5
        section = level.current_section()
        for i, layer in enumerate(section.layers):
            r = pygame.Rect(area.x+2, y, area.width-4, 18)
            pygame.draw.rect(surf, SYS_HIGHLIGHT if i==section.current_layer_idx else SYS_WINDOW, r)
            col = WHITE if i==section.current_layer_idx else SYS_TEXT
            draw_text(surf, layer.name, (r.x+5, r.y+1), col, FONT_SMALL)
            pygame.draw.circle(surf, GREEN if layer.visible else RED, (r.right-8, r.centery), 4)
            pygame.draw.rect(surf, GRAY if layer.locked else SYS_BTN_FACE, (r.right-20, r.y+2, 8, 8))
            y += 22

    def handle_click(self, pos, level):
        tab_y = self.rect.y + self.title_h + 2
        tab_w = self.rect.width // len(self.categories)
        for i, cat in enumerate(self.categories):
            r = pygame.Rect(self.rect.x + 2 + i * tab_w, tab_y, tab_w - 2, self.tab_h)
            if r.collidepoint(pos):
                self.current_category = cat
                return True
        content = pygame.Rect(self.rect.x + 2, tab_y + self.tab_h, self.rect.width - 4,
                              self.rect.height - self.title_h - self.tab_h - 4)
        if self._internal_cat() == "Layers":
            y = content.y+5
            section = level.current_section()
            for i, layer in enumerate(section.layers):
                r = pygame.Rect(content.x+2, y, content.width-4, 18)
                if r.collidepoint(pos):
                    if pos[0] > r.right-20:
                        layer.locked = not layer.locked
                    elif pos[0] > r.right-35:
                        layer.visible = not layer.visible
                    else:
                        section.current_layer_idx = i
                    return True
                y += 22
        else:
            items = self.items[self._internal_cat()]
            cols = 4
            for i, item in enumerate(items):
                r = pygame.Rect(content.x + 4 + (i % cols) * 38, content.y + 4 + (i // cols) * 38, 32, 32)
                if r.collidepoint(pos):
                    self.selected_item = item
                    return True
        return False


# -------------------------
# EDITOR
# -------------------------
class Editor:
    def __init__(self, level, screen, initial_path=None):
        self.screen = screen
        self.level = level
        self.camera = Camera(level.current_section().width, level.current_section().height)
        self.playtest_mode = False
        self.player = None
        self.undo_stack = []
        self.redo_stack = []
        self.sidebar = Sidebar()
        self.drag_draw = False
        self.drag_erase = False
        self.current_file = initial_path if initial_path else None
        self.selection = []
        self.clipboard = []
        self.tool = 'pencil'
        self.grid_enabled = True
        self.mouse_pos = (0,0)
        self.tooltip_text = ""
        self.status_msg = ""
        self._build_menu()
        self._build_toolbar()

